}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Role {
  ADMIN = 'ADMIN',
  USER = 'USER'
}

export enum LeaveStatus {
  PENDING = 'PENDING',
  APPROVED = 'APPROVED',
  REJECTED = 'REJECTED'
}

export enum LeaveType {
  ANNUAL = 'ANNUAL', // 일반 연차
  BONUS = 'BONUS',   // 보너스 연차
  BIRTHDAY = 'BIRTHDAY', // 생일 반차 (0일 차감)
  OFFICIAL = 'OFFICIAL' // 공결 (0일 차감)
}

export interface Employee {
  id: string;
  name: string;
  email: string;
  role: Role;
  hireDate: string; // ISO format
}

export interface BonusLeaveRecord {
  id: string;
  employeeId: string;
  amount: number;
  reason: string;
  createdAt: string;
}

export interface LeaveRequest {
  id: string;
  employeeId: string;
  type: LeaveType;
  startDate: string;
  endDate: string;
  status: LeaveStatus;
  reason: string;
  adminComment?: string;
  createdAt: string;
}

export interface Notification {
  id: string;
  employeeId: string;
  message: string;
  isRead: boolean;
  createdAt: string;
}

export interface LeaveBalance {
  accrued: number;
  bonus: number;
  usedAnnual: number;
  usedBonus: number;
  remainingAnnual: number;
  remainingBonus: number;
}

import { 
  differenceInMonths, 
  differenceInYears, 
  addYears, 
  isWithinInterval, 
  parseISO, 
  startOfDay,
  addDays,
  differenceInCalendarDays,
  format
} from 'date-fns';
import { LeaveType, LeaveRequest, LeaveStatus, BonusLeaveRecord, LeaveBalance } from '../types';

/**
 * 입사일 기준으로 현재 주기를 계산합니다.
 */
export const getCurrentCycle = (hireDateStr: string, today: Date = new Date()) => {
  const hireDate = parseISO(hireDateStr);
  const yearsSinceHire = differenceInYears(today, hireDate);
  const cycleStart = addYears(hireDate, yearsSinceHire);

  // 만약 오늘이 올해 입사기념일 전이라면 작년 주기로 계산
  if (cycleStart > today) {
    const prevStart = addYears(hireDate, yearsSinceHire - 1);
    return {
      start: startOfDay(prevStart),
      end: startOfDay(addYears(prevStart, 1)),
      tenureYears: yearsSinceHire - 1
    };
  }

  return {
    start: startOfDay(cycleStart),
    end: startOfDay(addYears(cycleStart, 1)),
    tenureYears: yearsSinceHire
  };
};

/**
 * 입사일 기준 현재 주기(1년) 내에 발생한 연차를 계산합니다.
 */
export const calculateAccruedInCycle = (hireDateStr: string, today: Date = new Date()) => {
  const hireDate = parseISO(hireDateStr);
  const totalMonths = differenceInMonths(today, hireDate);
  const yearsSinceHire = differenceInYears(today, hireDate);

  // 1년 미만: 1개월 만근 시 1개씩 (최대 11개)
  if (yearsSinceHire < 1) {
    return Math.min(totalMonths, 11);
  }

  // 1년 이상: 매년 리셋되어 15개 발생
  return 15;
};

/**
 * 사용자의 전체 연차 밸런스를 계산합니다.
 */
export const getEmployeeLeaveBalance = (
  hireDateStr: string,
  requests: LeaveRequest[],
  bonusRecords: BonusLeaveRecord[]
): LeaveBalance => {
  const today = new Date();
  const cycle = getCurrentCycle(hireDateStr, today);

  // 1. 이번 주기 발생 연차
  const accrued = calculateAccruedInCycle(hireDateStr, today);

  // 2. 해당 직원의 보너스 연차 총합 (보너스는 리셋 정책이 따로 없다고 가정하여 누적)
  const bonus = bonusRecords
    .filter(r => r.employeeId === r.employeeId) // 실제론 밖에서 필터링해서 옴
    .reduce((sum, r) => sum + r.amount, 0);

  // 3. 이번 주기 내 사용한 연차/보너스 (승인된 것만)
  let usedAnnual = 0;
  let usedBonus = 0;

  requests.forEach(req => {
    if (req.status !== LeaveStatus.APPROVED) return;

    const start = parseISO(req.startDate);
    const end = parseISO(req.endDate);
    const days = differenceInCalendarDays(end, start) + 1;

    // 이번 주기 내에 포함되는지 확인 (시작일 기준)
    if (isWithinInterval(start, { start: cycle.start, end: cycle.end })) {
      if (req.type === LeaveType.ANNUAL) {
        usedAnnual += days;
      } else if (req.type === LeaveType.BONUS) {
        usedBonus += days;
      }
      // BIRTHDAY, OFFICIAL은 차감 0
    }
  });

  return {
    accrued,
    bonus,
    usedAnnual,
    usedBonus,
    remainingAnnual: Math.max(0, accrued - usedAnnual),
    remainingBonus: Math.max(0, bonus - usedBonus)
  };
};

import { GoogleGenAI } from "@google/genai";

export const askGemini = async (prompt: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: `당신은 회사의 인사 관리 AI 도우미입니다. 
        한국의 근로기준법과 회사의 연차 정책(1년 미만 월 1개, 1년 이상 연 15개 리셋)을 바탕으로 친절하게 답변해주세요.
        연차 종류: 일반연차, 보너스연차, 생일반차(0일차감), 공결(0일차감).
        답변은 간결하고 명확하게 한국어로 작성하세요.`
      }
    });
    return response.text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "죄송합니다. AI 답변을 생성하는 중 오류가 발생했습니다.";
  }
};

