        >
          <PlusCircle size={20} />
          <span>연차 신청하기</span>
        </button>
      </header>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-sm font-medium text-slate-500 mb-1">총 발생 연차</p>
          <div className="flex items-baseline space-x-1">
            <span className="text-3xl font-bold text-blue-600">{balance.accrued + balance.bonus}</span>
            <span className="text-slate-400 font-medium">일</span>
          </div>
          <p className="text-xs text-slate-400 mt-2">일반 {balance.accrued} / 보너스 {balance.bonus}</p>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-sm font-medium text-slate-500 mb-1">사용 연차</p>
          <div className="flex items-baseline space-x-1">
            <span className="text-3xl font-bold text-slate-800">{balance.usedAnnual + balance.usedBonus}</span>
            <span className="text-slate-400 font-medium">일</span>
          </div>
          <p className="text-xs text-slate-400 mt-2">일반 {balance.usedAnnual} / 보너스 {balance.usedBonus}</p>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-blue-100 ring-2 ring-blue-50">
          <p className="text-sm font-medium text-blue-600 mb-1">잔여 연차</p>
          <div className="flex items-baseline space-x-1">
            <span className="text-3xl font-bold text-blue-700">{balance.remainingAnnual + balance.remainingBonus}</span>
            <span className="text-blue-400 font-medium">일</span>
          </div>
          <p className="text-xs text-blue-400 mt-2">사용 가능일 기준</p>
        </div>
      </div>

      {/* AI Assistant Section */}
      <div className="bg-gradient-to-r from-blue-50 to-indigo-50 p-6 rounded-2xl border border-blue-100">
        <div className="flex items-center space-x-2 mb-4">
          <MessageSquare className="text-blue-600" size={24} />
