              <th className="px-6 py-4 text-sm font-bold text-slate-600">상태</th>
              <th className="px-6 py-4 text-sm font-bold text-slate-600 text-right">관리</th>
            </tr>
          </thead>
          <tbody className="divide-y">
            {requests.map(req => {
              const emp = employees.find(e => e.id === req.employeeId);
              return (
                <tr key={req.id} className="hover:bg-slate-50">
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-800">{emp?.name || 'Unknown'}</div>
                    <div className="text-xs text-slate-500">{emp?.email}</div>
                  </td>
                  <td className="px-6 py-4 text-sm text-slate-600 font-medium">{req.type}</td>
                  <td className="px-6 py-4 text-sm text-slate-600">
                    {req.startDate} ~ {req.endDate}
