};

const AdminEmployees = ({ employees, requests, bonusRecords, setBonusRecords }: { employees: Employee[], requests: LeaveRequest[], bonusRecords: BonusLeaveRecord[], setBonusRecords: any }) => {
  const [selectedEmp, setSelectedEmp] = useState<Employee | null>(null);
  const [bonusAmount, setBonusAmount] = useState(0);

  const handleAddBonus = () => {
    if (!selectedEmp) return;
    const newRecord: BonusLeaveRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: selectedEmp.id,
      amount: bonusAmount,
      reason: '관리자 수기 추가',
      createdAt: new Date().toISOString()
    };
    setBonusRecords(prev => [...prev, newRecord]);
    setSelectedEmp(null);
    setBonusAmount(0);
    alert(`${selectedEmp.name}님에게 보너스 연차 ${bonusAmount}일이 추가되었습니다.`);
  };

  return (
    <div className="p-8 space-y-6">
      <h2 className="text-2xl font-bold">직원 연차 현황 관리</h2>
      <div className="grid grid-cols-1 gap-6">
        {employees.map(emp => {
          const empBonus = bonusRecords.filter(b => b.employeeId === emp.id);
          const balance = getEmployeeLeaveBalance(emp.hireDate, requests.filter(r => r.employeeId === emp.id), empBonus);
          return (
            <div key={emp.id} className="bg-white p-6 rounded-2xl border shadow-sm flex items-center justify-between">
              <div className="flex items-center space-x-6">
                <div className="w-12 h-12 bg-slate-100 rounded-full flex items-center justify-center text-slate-500 text-xl font-bold">
                  {emp.name[0]}
                </div>
                <div>
                  <h3 className="text-lg font-bold">{emp.name}</h3>
                  <p className="text-sm text-slate-500">입사일: {emp.hireDate}</p>
                </div>
              </div>

              <div className="flex space-x-8 text-center">
                <div>
                  <p className="text-xs text-slate-400 font-bold uppercase mb-1">발생 (일반+보너스)</p>
                  <p className="text-xl font-bold text-slate-700">{balance.accrued + balance.bonus}일</p>
                </div>
                <div>
                  <p className="text-xs text-slate-400 font-bold uppercase mb-1">사용</p>
                  <p className="text-xl font-bold text-slate-700">{balance.usedAnnual + balance.usedBonus}일</p>
                </div>
                <div>
                  <p className="text-xs text-blue-400 font-bold uppercase mb-1">잔여</p>
                  <p className="text-xl font-bold text-blue-600">{balance.remainingAnnual + balance.remainingBonus}일</p>
                </div>
              </div>

              <button 
                onClick={() => setSelectedEmp(emp)}
                className="bg-slate-100 hover:bg-slate-200 text-slate-700 px-4 py-2 rounded-lg font-bold transition-colors"
              >
                보너스 부여
              </button>
            </div>
          );
        })}
      </div>

      {selectedEmp && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl p-6 space-y-4">
            <h3 className="text-lg font-bold">{selectedEmp.name} 보너스 연차 부여</h3>
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-1">일수 (예: 1, 0.5)</label>
              <input 
                type="number" 
                value={bonusAmount}
                onChange={(e) => setBonusAmount(Number(e.target.value))}
                className="w-full border p-2 rounded-lg" 
              />
            </div>
            <div className="flex space-x-2 pt-4">
              <button 
                onClick={() => setSelectedEmp(null)}
                className="flex-1 px-4 py-2 border rounded-lg font-bold"
              >
                취소
              </button>
              <button 
                onClick={handleAddBonus}
                className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg font-bold"
              >
                부여하기
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

