const AdminEmployees = ({ employees, requests, bonusRecords, setBonusRecords }: { employees: Employee[], requests: LeaveRequest[], bonusRecords: BonusLeaveRecord[], setBonusRecords: any }) => {
  const [selectedEmp, setSelectedEmp] = useState<Employee | null>(null);
  const [bonusAmount, setBonusAmount] = useState(0);

  const handleAddBonus = () => {
    if (!selectedEmp) return;
    const newRecord: BonusLeaveRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: selectedEmp.id,
      amount: bonusAmount,
      reason: '관리자 수기 추가',
      createdAt: new Date().toISOString()
    };
    setBonusRecords((prev: BonusLeaveRecord[]) => [...prev, newRecord]);
    setSelectedEmp(null);
    setBonusAmount(0);
    alert(`${selectedEmp.name}님에게 보너스 연차 ${bonusAmount}일이 추가되었습니다.`);
  };

  return (
    <div className="p-4 md:p-8 space-y-6">
      <h2 className="text-xl md:text-2xl font-bold">직원 연차 현황 관리</h2>
      <div className="grid grid-cols-1 gap-4 md:gap-6">
        {employees.map(emp => {
          const empBonus = bonusRecords.filter(b => b.employeeId === emp.id);
          const balance = getEmployeeLeaveBalance(emp.hireDate, requests.filter(r => r.employeeId === emp.id), empBonus);
          return (
            <div key={emp.id} className="bg-white p-5 md:p-6 rounded-2xl border shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-6">
              <div className="flex items-center space-x-4 md:space-x-6">
                <div className="w-10 h-10 md:w-12 md:h-12 bg-slate-100 rounded-full flex items-center justify-center text-slate-500 text-lg md:text-xl font-bold flex-shrink-0">
                  {emp.name[0]}
                </div>
                <div>
                  <h3 className="text-base md:text-lg font-bold truncate">{emp.name}</h3>
                  <p className="text-xs md:text-sm text-slate-500">입사일: {emp.hireDate}</p>
                </div>
              </div>

              <div className="grid grid-cols-3 gap-4 md:space-x-8 text-center border-y md:border-none py-4 md:py-0">
                <div>
                  <p className="text-[10px] text-slate-400 font-bold uppercase mb-1">발생</p>
                  <p className="text-sm md:text-xl font-bold text-slate-700">{balance.accrued + balance.bonus}일</p>
                </div>
                <div>
                  <p className="text-[10px] text-slate-400 font-bold uppercase mb-1">사용</p>
                  <p className="text-sm md:text-xl font-bold text-slate-700">{balance.usedAnnual + balance.usedBonus}일</p>
                </div>
                <div>
                  <p className="text-[10px] text-blue-400 font-bold uppercase mb-1">잔여</p>
                  <p className="text-sm md:text-xl font-bold text-blue-600">{balance.remainingAnnual + balance.remainingBonus}일</p>
                </div>
              </div>

              <button 
                onClick={() => setSelectedEmp(emp)}
                className="bg-slate-100 hover:bg-slate-200 text-slate-700 px-4 py-2 rounded-lg font-bold text-sm transition-colors w-full md:w-auto"
              >
                보너스 부여
              </button>
            </div>
          );
        })}
      </div>

      {selectedEmp && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-[100] p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl p-6 space-y-4 shadow-2xl animate-in zoom-in-95 duration-200">
            <h3 className="text-lg font-bold">{selectedEmp.name} 보너스 연차 부여</h3>
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-1">일수 (예: 1, 0.5)</label>
              <input 
                type="number" 
                value={bonusAmount}
                onChange={(e) => setBonusAmount(Number(e.target.value))}
                className="w-full border p-2 rounded-lg" 
              />
            </div>
            <div className="flex space-x-2 pt-4">
              <button 
                onClick={() => setSelectedEmp(null)}
                className="flex-1 px-4 py-2 border rounded-lg font-bold text-slate-600 bg-white"
              >
                취소
              </button>
              <button 
                onClick={handleAddBonus}
                className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg font-bold"
              >
                부여하기
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

