const AdminEmployees = ({ employees, requests, bonusRecords, setBonusRecords }: { employees: Employee[], requests: LeaveRequest[], bonusRecords: BonusLeaveRecord[], setBonusRecords: any }) => {
  const [bonusTarget, setBonusTarget] = useState<Employee | null>(null);
  const [detailTarget, setDetailTarget] = useState<Employee | null>(null);
  const [bonusValue, setBonusValue] = useState<string>("");

  const handleAddBonus = () => {
    if (!bonusTarget || bonusValue === "" || isNaN(Number(bonusValue))) return;
    const newRecord: BonusLeaveRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: bonusTarget.id,
      amount: Number(bonusValue),
      reason: '관리자 수기 추가',
      createdAt: new Date().toISOString()
    };
    setBonusRecords((prev: BonusLeaveRecord[]) => [...prev, newRecord]);
    setBonusTarget(null);
    setBonusValue("");
    alert(`${bonusTarget.name}님에게 보너스 연차 ${bonusValue}일이 추가되었습니다.`);
  };

  const getEmpRequests = (empId: string) => requests.filter(r => r.employeeId === empId);
  const getEmpBonus = (empId: string) => bonusRecords.filter(b => b.employeeId === empId);

  return (
    <div className="p-4 md:p-8 space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-xl md:text-2xl font-bold">직원 연차 현황 관리</h2>
        <span className="text-xs text-slate-400 font-medium">카드를 클릭하면 상세 현황을 볼 수 있습니다.</span>
      </div>

      <div className="grid grid-cols-1 gap-4 md:gap-6">
        {employees.map(emp => {
          const empBonus = getEmpBonus(emp.id);
          const balance = getEmployeeLeaveBalance(emp.hireDate, getEmpRequests(emp.id), empBonus);
          return (
            <div 
              key={emp.id} 
              onClick={() => setDetailTarget(emp)}
              className="bg-white p-5 md:p-6 rounded-2xl border shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-6 hover:border-blue-300 hover:shadow-md transition-all cursor-pointer group"
            >
              <div className="flex items-center space-x-4 md:space-x-6">
                <div className="w-10 h-10 md:w-12 md:h-12 bg-slate-100 rounded-full flex items-center justify-center text-slate-500 text-lg md:text-xl font-bold flex-shrink-0 group-hover:bg-blue-50 group-hover:text-blue-600 transition-colors">
                  {emp.name[0]}
                </div>
                <div className="overflow-hidden">
                  <h3 className="text-base md:text-lg font-bold truncate group-hover:text-blue-700 transition-colors">{emp.name}</h3>
                  <p className="text-xs md:text-sm text-slate-500">입사일: {emp.hireDate}</p>
                </div>
              </div>

              <div className="grid grid-cols-3 gap-4 md:space-x-8 text-center border-y md:border-none py-4 md:py-0">
                <div>
                  <p className="text-[10px] text-slate-400 font-bold uppercase mb-1">발생</p>
                  <p className="text-sm md:text-xl font-bold text-slate-700">{balance.accrued + balance.bonus}일</p>
                </div>
                <div>
                  <p className="text-[10px] text-slate-400 font-bold uppercase mb-1">사용</p>
                  <p className="text-sm md:text-xl font-bold text-slate-700">{balance.usedAnnual + balance.usedBonus}일</p>
                </div>
                <div>
                  <p className="text-[10px] text-blue-400 font-bold uppercase mb-1">잔여</p>
                  <p className="text-sm md:text-xl font-bold text-blue-600">{balance.remainingAnnual + balance.remainingBonus}일</p>
                </div>
              </div>

              <button 
                onClick={(e) => {
                  e.stopPropagation();
                  setBonusTarget(emp);
                }}
                className="bg-slate-100 hover:bg-slate-200 text-slate-700 px-4 py-2 rounded-lg font-bold text-sm transition-colors w-full md:w-auto"
              >
                보너스 부여
              </button>
            </div>
          );
        })}
      </div>

      {/* Bonus Modal */}
      {bonusTarget && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-[110] p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl p-6 space-y-4 shadow-2xl animate-in zoom-in-95 duration-200">
            <h3 className="text-lg font-bold">{bonusTarget.name} 보너스 연차 부여</h3>
            <p className="text-xs text-slate-500">일수를 숫자로 입력해 주세요. (예: 1, 0.5)</p>
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-1">일수</label>
              <input 
                type="number" 
                step="0.5"
                placeholder="0"
                value={bonusValue}
                onChange={(e) => setBonusValue(e.target.value)}
                autoFocus
                className="w-full border p-3 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all font-bold text-lg" 
              />
            </div>
            <div className="flex space-x-2 pt-4">
              <button 
                onClick={() => {
                  setBonusTarget(null);
                  setBonusValue("");
                }}
                className="flex-1 px-4 py-2 border rounded-lg font-bold text-slate-600 bg-white"
              >
                취소
              </button>
              <button 
                onClick={handleAddBonus}
                disabled={bonusValue === "" || isNaN(Number(bonusValue))}
                className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg font-bold disabled:opacity-50"
              >
