                  <span className="text-[10px] bg-blue-50 text-blue-600 px-2 py-0.5 rounded-full font-bold">전체 {getEmpRequests(detailTarget.id).length}건</span>
                </div>

                <div className="border rounded-2xl overflow-hidden divide-y">
                  {getEmpRequests(detailTarget.id).length > 0 ? getEmpRequests(detailTarget.id).map(req => (
                    <div key={req.id} className="p-4 flex items-center justify-between hover:bg-slate-50 transition-colors">
                      <div className="flex flex-col">
                        <span className="text-xs font-bold text-slate-700">{req.startDate} ~ {req.endDate}</span>
                        <div className="flex items-center space-x-2 mt-1">
