              <Route path="/history" element={
                <div className="p-4 md:p-8 max-w-7xl mx-auto">
                  <h2 className="text-xl md:text-2xl font-bold mb-6">나의 연차 히스토리</h2>
                  <div className="bg-white rounded-2xl border overflow-hidden shadow-sm">
                    <div className="overflow-x-auto">
                      <table className="w-full text-left min-w-[500px]">
                        <thead className="bg-slate-50 border-b">
                          <tr>
                            <th className="px-6 py-4 text-xs md:text-sm font-bold">일자</th>
                            <th className="px-6 py-4 text-xs md:text-sm font-bold">종류</th>
                            <th className="px-6 py-4 text-xs md:text-sm font-bold">상태</th>
                            <th className="px-6 py-4 text-xs md:text-sm font-bold">사유</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y">
                          {userRequests.map(req => (
                            <tr key={req.id} className="hover:bg-slate-50/50">
                              <td className="px-6 py-4 text-xs md:text-sm">{req.startDate} ~ {req.endDate}</td>
                              <td className="px-6 py-4 text-xs md:text-sm font-medium">{req.type}</td>
                              <td className="px-6 py-4 text-xs md:text-sm">
                                <span className={`px-2 py-1 rounded-full text-[10px] font-bold ${
                                  req.status === LeaveStatus.APPROVED ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'
                                }`}>{req.status}</span>
                              </td>
                              <td className="px-6 py-4 text-xs md:text-sm text-slate-500 max-w-[200px] truncate">{req.reason}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </div>
              } />

              {currentUser.role === Role.ADMIN && (
                <>
                  <Route path="/admin/employees" element={<AdminEmployees employees={MOCK_EMPLOYEES} requests={requests} bonusRecords={bonusRecords} setBonusRecords={setBonusRecords} />} />
                  <Route path="/admin/requests" element={<AdminRequests requests={requests} setRequests={setRequests} employees={MOCK_EMPLOYEES} />} />
                </>
              )}

              <Route path="*" element={<Navigate to="/dashboard" replace />} />
            </Routes>
          </main>
        </div>
      </div>
    </Router>
  );
}

