const Dashboard = ({ employee, requests, bonusRecords }: { employee: Employee, requests: LeaveRequest[], bonusRecords: BonusLeaveRecord[] }) => {
  const balance = useMemo(() => getEmployeeLeaveBalance(employee.hireDate, requests, bonusRecords), [employee.hireDate, requests, bonusRecords]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [aiResponse, setAiResponse] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Leave Form State
  const [formData, setFormData] = useState({
    type: LeaveType.ANNUAL,
    startDate: format(new Date(), 'yyyy-MM-dd'),
    endDate: format(new Date(), 'yyyy-MM-dd'),
    reason: ''
  });

  const duration = useMemo(() => {
    const s = parseISO(formData.startDate);
    const e = parseISO(formData.endDate);
    if (!isValid(s) || !isValid(e)) return 0;
    const diff = differenceInCalendarDays(e, s) + 1;
    return diff > 0 ? diff : 0;
  }, [formData.startDate, formData.endDate]);

  const deduction = useMemo(() => {
    if (formData.type === LeaveType.BIRTHDAY || formData.type === LeaveType.OFFICIAL) return 0;
    return duration;
  }, [formData.type, duration]);

  const handleAiAsk = async () => {
    setIsAiLoading(true);
    const res = await askGemini(`제 입사일은 ${employee.hireDate}입니다. 현재 저의 연차 발생 원리와 남은 연차에 대해 요약해주세요.`);
    setAiResponse(res || '');
    setIsAiLoading(false);
  };

  return (
    <div className="p-4 md:p-8 space-y-6 md:space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-7xl mx-auto">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-xl md:text-2xl font-bold text-slate-900">안녕하세요, {employee.name}님!</h2>
          <p className="text-sm md:text-base text-slate-500">오늘도 활기찬 하루 되세요.</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2.5 rounded-xl font-bold flex items-center justify-center space-x-2 transition-all shadow-lg hover:shadow-blue-200"
        >
          <PlusCircle size={20} />
          <span>연차 신청하기</span>
        </button>
      </header>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 md:gap-6">
        <div className="bg-white p-5 md:p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-sm font-medium text-slate-500 mb-1">총 발생 연차</p>
          <div className="flex items-baseline space-x-1">
            <span className="text-2xl md:text-3xl font-bold text-blue-600">{balance.accrued + balance.bonus}</span>
            <span className="text-slate-400 font-medium">일</span>
          </div>
          <p className="text-[10px] md:text-xs text-slate-400 mt-2">일반 {balance.accrued} / 보너스 {balance.bonus}</p>
        </div>
        <div className="bg-white p-5 md:p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-sm font-medium text-slate-500 mb-1">사용 연차</p>
          <div className="flex items-baseline space-x-1">
            <span className="text-2xl md:text-3xl font-bold text-slate-800">{balance.usedAnnual + balance.usedBonus}</span>
            <span className="text-slate-400 font-medium">일</span>
          </div>
          <p className="text-[10px] md:text-xs text-slate-400 mt-2">일반 {balance.usedAnnual} / 보너스 {balance.usedBonus}</p>
        </div>
        <div className="bg-white p-5 md:p-6 rounded-2xl shadow-sm border border-blue-100 ring-2 ring-blue-50">
          <p className="text-sm font-medium text-blue-600 mb-1">잔여 연차</p>
          <div className="flex items-baseline space-x-1">
            <span className="text-2xl md:text-3xl font-bold text-blue-700">{balance.remainingAnnual + balance.remainingBonus}</span>
            <span className="text-blue-400 font-medium">일</span>
          </div>
          <p className="text-[10px] md:text-xs text-blue-400 mt-2">사용 가능일 기준</p>
        </div>
      </div>

      <div className="bg-gradient-to-r from-blue-50 to-indigo-50 p-5 md:p-6 rounded-2xl border border-blue-100">
        <div className="flex items-center space-x-2 mb-4">
          <MessageSquare className="text-blue-600" size={20} />
          <h3 className="text-base md:text-lg font-bold text-blue-900">AI 인사 도우미</h3>
        </div>
        <div className="space-y-4">
          {aiResponse ? (
            <div className="bg-white/80 p-4 rounded-xl text-slate-700 text-sm leading-relaxed border border-white whitespace-pre-wrap">
              {aiResponse}
            </div>
          ) : (
            <p className="text-sm text-slate-600">내 연차 정책이나 남은 연차에 대해 궁금한 점이 있나요?</p>
          )}
          <button 
            disabled={isAiLoading}
            onClick={handleAiAsk}
            className="text-sm font-bold text-blue-600 hover:text-blue-700 disabled:opacity-50"
          >
            {isAiLoading ? '분석 중...' : '나의 연차 상태 분석 요청하기 →'}
          </button>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-100 overflow-hidden shadow-sm">
        <div className="p-4 border-b bg-slate-50/50">
          <h3 className="font-bold text-slate-800">최근 신청 내역</h3>
        </div>
        <div className="divide-y overflow-x-auto">
          {requests.length > 0 ? requests.slice(0, 5).map(req => (
            <div key={req.id} className="p-4 flex items-center justify-between hover:bg-slate-50 transition-colors min-w-[300px]">
              <div className="flex items-center space-x-4">
                <div className={`w-2 h-2 rounded-full flex-shrink-0 ${
                  req.status === LeaveStatus.APPROVED ? 'bg-green-500' : 
                  req.status === LeaveStatus.REJECTED ? 'bg-red-500' : 'bg-amber-500'
                }`} />
                <div className="overflow-hidden">
                  <p className="font-bold text-sm text-slate-800 truncate">{req.type} - {req.startDate} ~ {req.endDate}</p>
                  <p className="text-xs text-slate-500 truncate">{req.reason}</p>
                </div>
              </div>
              <span className={`text-[10px] md:text-xs font-bold px-2 py-1 rounded-full whitespace-nowrap ml-4 ${
                req.status === LeaveStatus.APPROVED ? 'bg-green-100 text-green-700' : 
                req.status === LeaveStatus.REJECTED ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'
              }`}>
                {req.status === LeaveStatus.APPROVED ? '승인됨' : 
                 req.status === LeaveStatus.REJECTED ? '거절됨' : '대기중'}
              </span>
            </div>
          )) : (
            <div className="p-8 text-center text-slate-400 font-medium">신청 내역이 없습니다.</div>
          )}
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-[100] p-4">
          <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-6 border-b flex justify-between items-center">
              <h3 className="text-xl font-bold">연차 신청</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
            </div>
            <div className="p-6 space-y-5 max-h-[70vh] overflow-y-auto">
              <div>
                <label className="block text-sm font-bold text-slate-700 mb-1.5">연차 종류</label>
                <select 
                  className="w-full border-slate-200 border p-2.5 rounded-xl bg-white focus:ring-2 focus:ring-blue-500 outline-none"
                  value={formData.type}
                  onChange={e => setFormData({...formData, type: e.target.value as LeaveType})}
                >
                  <option value={LeaveType.ANNUAL}>일반 연차 (기간 전체 차감)</option>
                  <option value={LeaveType.BONUS}>보너스 연차 (기간 전체 차감)</option>
                  <option value={LeaveType.BIRTHDAY}>생일 반차 (0일 차감)</option>
                  <option value={LeaveType.OFFICIAL}>공결 (0일 차감)</option>
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-bold text-slate-700 mb-1.5">시작일</label>
                  <input 
                    type="date" 
                    className="w-full border-slate-200 border p-2.5 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" 
                    value={formData.startDate}
                    onChange={e => setFormData({...formData, startDate: e.target.value})}
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-slate-700 mb-1.5">종료일</label>
                  <input 
                    type="date" 
                    className="w-full border-slate-200 border p-2.5 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none" 
                    value={formData.endDate}
                    onChange={e => setFormData({...formData, endDate: e.target.value})}
                  />
                </div>
              </div>

              {/* Deduction Info */}
              <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 flex items-center justify-between">
                <div className="flex items-center space-x-2 text-blue-700">
                  <Clock size={18} />
                  <span className="text-sm font-bold">총 신청 기간</span>
                </div>
                <div className="text-right">
                  <span className="text-xl font-black text-blue-700">{duration}</span>
                  <span className="text-sm font-bold text-blue-600 ml-1">일</span>
                  <p className="text-[10px] text-blue-400 mt-0.5 font-bold">
                    차감 예정: {deduction}일
                  </p>
                </div>
              </div>

              <div>
                <label className="block text-sm font-bold text-slate-700 mb-1.5">사유</label>
                <textarea 
                  className="w-full border-slate-200 border p-3 rounded-xl h-24 focus:ring-2 focus:ring-blue-500 outline-none" 
                  placeholder="사유를 입력하세요."
                  value={formData.reason}
                  onChange={e => setFormData({...formData, reason: e.target.value})}
                ></textarea>
              </div>
            </div>
            <div className="p-6 bg-slate-50 flex space-x-3">
              <button 
                onClick={() => setIsModalOpen(false)}
                className="flex-1 px-4 py-2.5 border rounded-xl font-bold text-slate-600 hover:bg-white bg-white/50 transition-colors"
              >
                취소
              </button>
              <button 
                onClick={() => {
                  if (duration <= 0) return alert("날짜를 확인해 주세요.");
                  alert(`${formData.type} 신청이 완료되었습니다.\n기간: ${formData.startDate} ~ ${formData.endDate}\n총 ${deduction}일 차감됩니다.`);
                  setIsModalOpen(false);
                }}
                className="flex-1 px-4 py-2.5 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-md shadow-blue-100"
              >
                신청하기
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const AdminRequests = ({ requests, setRequests, employees }: { requests: LeaveRequest[], setRequests: any, employees: Employee[] }) => {
  const handleAction = (id: string, status: LeaveStatus) => {
    setRequests((prev: LeaveRequest[]) => prev.map(r => r.id === id ? { ...r, status } : r));
    alert(`${status === LeaveStatus.APPROVED ? '승인' : '거절'} 처리가 완료되었습니다.`);
  };

  return (
    <div className="p-4 md:p-8 space-y-6">
      <h2 className="text-xl md:text-2xl font-bold">연차 신청 승인 관리</h2>
      <div className="bg-white rounded-2xl border overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-left min-w-[600px]">
            <thead className="bg-slate-50 border-b">
              <tr>
                <th className="px-6 py-4 text-xs md:text-sm font-bold text-slate-600">직원명</th>
                <th className="px-6 py-4 text-xs md:text-sm font-bold text-slate-600">종류</th>
                <th className="px-6 py-4 text-xs md:text-sm font-bold text-slate-600">기간</th>
                <th className="px-6 py-4 text-xs md:text-sm font-bold text-slate-600">상태</th>
                <th className="px-6 py-4 text-xs md:text-sm font-bold text-slate-600 text-right">관리</th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {requests.map(req => {
                const emp = employees.find(e => e.id === req.employeeId);
                return (
                  <tr key={req.id} className="hover:bg-slate-50">
                    <td className="px-6 py-4">
                      <div className="font-bold text-sm text-slate-800">{emp?.name || 'Unknown'}</div>
                      <div className="text-[10px] md:text-xs text-slate-500">{emp?.email}</div>
                    </td>
                    <td className="px-6 py-4 text-xs md:text-sm text-slate-600 font-medium">{req.type}</td>
                    <td className="px-6 py-4 text-xs md:text-sm text-slate-600">
                      {req.startDate} ~ {req.endDate}
                    </td>
                    <td className="px-6 py-4">
                      <span className={`text-[10px] font-bold px-2 py-1 rounded-full ${
                        req.status === LeaveStatus.APPROVED ? 'bg-green-100 text-green-700' : 
                        req.status === LeaveStatus.REJECTED ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'
                      }`}>
                        {req.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right space-x-2">
                      {req.status === LeaveStatus.PENDING && (
                        <div className="flex justify-end space-x-1">
                          <button 
                            onClick={() => handleAction(req.id, LeaveStatus.APPROVED)}
                            className="p-1.5 text-green-600 hover:bg-green-50 rounded-lg transition-colors"
                            title="승인"
                          >
                            <CheckCircle size={18} />
                          </button>
                          <button 
                            onClick={() => handleAction(req.id, LeaveStatus.REJECTED)}
                            className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                            title="거절"
                          >
                            <XCircle size={18} />
                          </button>
                        </div>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

const AdminEmployees = ({ employees, requests, bonusRecords, setBonusRecords }: { employees: Employee[], requests: LeaveRequest[], bonusRecords: BonusLeaveRecord[], setBonusRecords: any }) => {
  const [bonusTarget, setBonusTarget] = useState<Employee | null>(null);
  const [detailTarget, setDetailTarget] = useState<Employee | null>(null);
