              } />

              {currentUser.role === Role.ADMIN && (
                <>
                  <Route path="/admin/employees" element={
                    <AdminEmployees 
                      employees={employees} 
                      setEmployees={setEmployees}
                      requests={requests} 
                      bonusRecords={bonusRecords} 
                      setBonusRecords={setBonusRecords} 
                    />
                  } />
                  <Route path="/admin/requests" element={
                    <AdminRequests 
                      requests={requests} 
                      setRequests={setRequests} 
                      employees={employees} 
