      id: Math.random().toString(36).substr(2, 9),
      name: newEmp.name,
      email: newEmp.email,
      hireDate: newEmp.hireDate,
      role: newEmp.role
    };

    setEmployees((prev: Employee[]) => [...prev, newEmployee]);
    setIsAddModalOpen(false);
    setNewEmp({
      name: '',
      email: '',
      hireDate: format(new Date(), 'yyyy-MM-dd'),
      role: Role.USER
    });
    alert(`${newEmployee.name} 직원이 등록되었습니다.`);
