    const newRequest: LeaveRequest = {
      ...newReqData,
      id: Math.random().toString(36).substr(2, 9),
      status: LeaveStatus.PENDING,
      createdAt: new Date().toISOString(),
    };
    setRequests(prev => [...prev, newRequest]);
