import React, { useState, useMemo, useEffect } from 'react';
import ReactDOM from 'react-dom/client';
import { 
  HashRouter as Router, Routes, Route, Navigate, Link, useLocation 
} from 'react-router-dom';
import { 
  LayoutDashboard, Users, Calendar, Bell, LogOut, User as UserIcon,
  CheckCircle, XCircle, PlusCircle, MessageSquare, History, Menu, X,
  Info, Clock, UserPlus, FileText, TrendingUp, Award
} from 'lucide-react';
import { 
  differenceInMonths, differenceInYears, addYears, isWithinInterval, 
  parseISO, startOfDay, isWeekend, eachDayOfInterval, format, isValid,
  addMonths
} from 'date-fns';
import { GoogleGenAI } from "@google/genai";

// --- 1. TYPES & CONSTANTS ---
const Role = { ADMIN: 'ADMIN', USER: 'USER' };
const LeaveStatus = { PENDING: 'PENDING', APPROVED: 'APPROVED', REJECTED: 'REJECTED' };
const LeaveType = {
  ANNUAL: 'ANNUAL',
  BONUS: 'BONUS',
  MORNING_HALF: 'MORNING_HALF',
  AFTERNOON_HALF: 'AFTERNOON_HALF',
  BIRTHDAY: 'BIRTHDAY',
  OFFICIAL: 'OFFICIAL'
};

const INITIAL_EMPLOYEES = [
  { id: '1', name: '김관리', email: 'admin@company.com', role: Role.ADMIN, hireDate: '2020-01-01' },
  { id: '2', name: '이직원', email: 'user@company.com', role: Role.USER, hireDate: '2023-05-15' },
  { id: '3', name: '박신입', email: 'new@company.com', role: Role.USER, hireDate: '2024-02-10' },
];

// --- 2. UTILS ---
const calculateWorkdays = (start, end) => {
  if (start > end) return 0;
  try {
    const days = eachDayOfInterval({ start, end });
    return days.filter(day => !isWeekend(day)).length;
  } catch (e) { return 0; }
};

const getCurrentCycle = (hireDateStr, today = new Date()) => {
  const hireDate = parseISO(hireDateStr);
  const yearsSinceHire = differenceInYears(today, hireDate);
  let cycleStart = addYears(hireDate, yearsSinceHire);
  if (cycleStart > today) {
    cycleStart = addYears(hireDate, yearsSinceHire - 1);
  }
  return { start: startOfDay(cycleStart), end: startOfDay(addYears(cycleStart, 1)) };
};

const calculateAccruedInCycle = (hireDateStr, today = new Date()) => {
  const hireDate = parseISO(hireDateStr);
  const totalMonths = differenceInMonths(today, hireDate);
  const yearsSinceHire = differenceInYears(today, hireDate);
  if (yearsSinceHire < 1) return Math.min(totalMonths, 11);
  const additionalDays = Math.floor((yearsSinceHire - 1) / 2);
  return Math.min(15 + additionalDays, 25);
};

const getEmployeeLeaveBalance = (hireDateStr, requests, bonusRecords) => {
  const today = new Date();
  const cycle = getCurrentCycle(hireDateStr, today);
  const accrued = calculateAccruedInCycle(hireDateStr, today);
  const bonus = bonusRecords.reduce((sum, r) => sum + r.amount, 0);

  let usedAnnual = 0;
  let usedBonus = 0;

  requests.forEach(req => {
    if (req.status !== LeaveStatus.APPROVED) return;
    const start = parseISO(req.startDate);
    const end = parseISO(req.endDate);
    const workdays = calculateWorkdays(start, end);
    let deduction = workdays;
    if (req.type === LeaveType.MORNING_HALF || req.type === LeaveType.AFTERNOON_HALF) deduction = workdays * 0.5;
    else if (req.type === LeaveType.BIRTHDAY || req.type === LeaveType.OFFICIAL) deduction = 0;

    if (isWithinInterval(start, { start: cycle.start, end: cycle.end })) {
      if (req.type === LeaveType.BONUS) usedBonus += deduction;
      else usedAnnual += deduction;
    }
  });

  return {
    accrued, bonus, usedAnnual, usedBonus,
    remainingAnnual: Math.max(0, accrued - usedAnnual),
    remainingBonus: Math.max(0, bonus - usedBonus)
  };
};

// --- 3. AI SERVICE ---
const askGemini = async (prompt) => {
  const apiKey = process.env.API_KEY || '';
  if (!apiKey) return "API 키가 설정되지 않았습니다. Vercel 설정에서 API_KEY를 등록해주세요.";
  const ai = new GoogleGenAI({ apiKey });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: `당신은 회사의 인사 관리 AI 도우미입니다. 한국의 근로기준법과 회사의 연차 정책(1년 미만 월 1회, 1년 이상 15일+@, 반차 0.5일 차감 등)을 바탕으로 친절하게 한국어로 설명하세요.`
      }
    });
    return response.text;
  } catch (error) {
    return "AI 답변을 가져오는데 실패했습니다.";
  }
};

