            <div className="grid grid-cols-2 gap-4">
              <input type="date" className="border p-2 rounded-lg" value={form.startDate} onChange={e => setForm({...form, startDate: e.target.value})}/>
              <input type="date" className="border p-2 rounded-lg" value={form.endDate} onChange={e => setForm({...form, endDate: e.target.value})}/>
            </div>
            <div className="bg-blue-50 p-3 rounded-lg flex justify-between"><span>예상 차감 일수</span><span className="font-bold">{deduction}일</span></div>
            <textarea className="w-full border p-2 rounded-lg h-20" placeholder="사유를 입력하세요" value={form.reason} onChange={e => setForm({...form, reason: e.target.value})} />
            <div className="flex gap-2">
              <button onClick={() => setIsModalOpen(false)} className="flex-1 p-2 bg-slate-100 rounded-lg">취소</button>
              <button onClick={() => { onAddRequest({...form, employeeId: employee.id}); setIsModalOpen(false); }} className="flex-1 p-2 bg-blue-600 text-white rounded-lg">신청</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// --- 5. MAIN APP ---
function App() {
  const [user, setUser] = useState(null);
  const [employees, setEmployees] = useState(INITIAL_EMPLOYEES);
  const [requests, setRequests] = useState([]);
  const [bonusRecords, setBonusRecords] = useState([]);
