  const userRequests = requests.filter(r => r.employeeId === user.id);
  const userBonus = bonusRecords.filter(b => b.employeeId === user.id);

  return (
    <Router>
      <div className="flex h-screen overflow-hidden">
        <Sidebar currentUser={user} onLogout={() => setUser(null)} isOpen={sidebarOpen} setIsOpen={setSidebarOpen} />
        <div className="flex-1 flex flex-col min-w-0">
          <header className="bg-white border-b p-3 md:hidden flex justify-between items-center">
            <button onClick={() => setSidebarOpen(true)}><Menu/></button>
            <span className="font-bold text-blue-600">SmartLeave</span>
            <div className="w-6"/>
          </header>
          <main className="flex-1 overflow-y-auto">
            <Routes>
              <Route path="/dashboard" element={<Dashboard employee={user} requests={userRequests} bonusRecords={userBonus} onAddRequest={(d) => setRequests([...requests, { ...d, id: Date.now().toString(), status: 'PENDING', createdAt: new Date().toISOString() }])} />} />
              <Route path="/history" element={<div className="p-8">
                <h2 className="text-2xl font-bold mb-4">연차 신청 내역</h2>
                <div className="bg-white rounded-xl shadow-sm border divide-y">
                  {userRequests.length > 0 ? userRequests.map(r => (
                    <div key={r.id} className="p-4 flex justify-between">
                      <div><p className="font-bold">{r.startDate} ~ {r.endDate}</p><p className="text-xs text-slate-500">{r.type} · {r.reason}</p></div>
                      <span className={`px-2 py-1 rounded-full text-[10px] font-bold h-fit ${r.status === 'APPROVED' ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>{r.status}</span>
                    </div>
                  )) : <p className="p-8 text-center text-slate-400">내역이 없습니다.</p>}
                </div>
              </div>} />
              {user.role === 'ADMIN' && (
                <Route path="/admin/requests" element={<div className="p-8">
                  <h2 className="text-2xl font-bold mb-4">승인 대기 중인 신청</h2>
                  <div className="bg-white rounded-xl shadow-sm border divide-y">
                    {requests.filter(r => r.status === 'PENDING').map(r => (
                      <div key={r.id} className="p-4 flex justify-between items-center">
                        <div><p className="font-bold">{employees.find(e => e.id === r.employeeId)?.name} - {r.type}</p><p className="text-xs">{r.startDate} ~ {r.endDate}</p></div>
                        <div className="flex gap-2">
                          <button onClick={() => setRequests(requests.map(req => req.id === r.id ? {...req, status: 'APPROVED'} : req))} className="text-green-600 p-2 border rounded-lg hover:bg-green-50"><CheckCircle size={20}/></button>
                          <button onClick={() => setRequests(requests.map(req => req.id === r.id ? {...req, status: 'REJECTED'} : req))} className="text-red-600 p-2 border rounded-lg hover:bg-red-50"><XCircle size={20}/></button>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>} />
              )}
              <Route path="*" element={<Navigate to="/dashboard" replace />} />
            </Routes>
          </main>
        </div>
      </div>
    </Router>
  );
}

