  const workdaysCount = useMemo(() => calculateWorkdays(parseISO(formData.startDate), parseISO(formData.endDate)), [formData.startDate, formData.endDate]);
  const deduction = useMemo(() => (formData.type === LeaveType.BIRTHDAY || formData.type === LeaveType.OFFICIAL) ? 0 : (formData.type.includes('HALF') ? workdaysCount * 0.5 : workdaysCount), [formData.type, workdaysCount]);

  const handleAiAsk = async () => {
    setIsAiLoading(true);
