// --- 1. TYPES ---
enum Role {
  ADMIN = 'ADMIN',
  USER = 'USER'
}

enum LeaveStatus {
  PENDING = 'PENDING',
  APPROVED = 'APPROVED',
  REJECTED = 'REJECTED'
}

enum LeaveType {
  ANNUAL = 'ANNUAL',
  BONUS = 'BONUS',
  MORNING_HALF = 'MORNING_HALF',
  AFTERNOON_HALF = 'AFTERNOON_HALF',
  BIRTHDAY = 'BIRTHDAY',
  OFFICIAL = 'OFFICIAL'
}

interface Employee {
  id: string;
  name: string;
  email: string;
  role: Role;
  hireDate: string;
}

interface BonusLeaveRecord {
  id: string;
  employeeId: string;
  amount: number;
  reason: string;
  createdAt: string;
}

interface LeaveRequest {
  id: string;
  employeeId: string;
  type: LeaveType;
  startDate: string;
  endDate: string;
  status: LeaveStatus;
  reason: string;
  createdAt: string;
}

interface LeaveBalance {
  accrued: number;
  bonus: number;
  usedAnnual: number;
  usedBonus: number;
  remainingAnnual: number;
  remainingBonus: number;
}

// --- 2. UTILS ---
const calculateWorkdays = (start: Date, end: Date): number => {
  if (start > end) return 0;
  try {
    const days = eachDayOfInterval({ start, end });
    return days.filter(day => !isWeekend(day)).length;
  } catch (e) { return 0; }
};

const getCurrentCycle = (hireDateStr: string, today: Date = new Date()) => {
  const hireDate = parseISO(hireDateStr);
  const yearsSinceHire = differenceInYears(today, hireDate);
  const cycleStart = addYears(hireDate, yearsSinceHire);
  if (cycleStart > today) {
    const prevStart = addYears(hireDate, yearsSinceHire - 1);
    return { start: startOfDay(prevStart), end: startOfDay(addYears(prevStart, 1)) };
  }
  return { start: startOfDay(cycleStart), end: startOfDay(addYears(cycleStart, 1)) };
};

const calculateAccruedInCycle = (hireDateStr: string, today: Date = new Date()) => {
  const hireDate = parseISO(hireDateStr);
  const totalMonths = differenceInMonths(today, hireDate);
  const yearsSinceHire = differenceInYears(today, hireDate);
  if (yearsSinceHire < 1) return Math.min(totalMonths, 11);
  const additionalDays = Math.floor((yearsSinceHire - 1) / 2);
  return Math.min(15 + additionalDays, 25);
};

const getEmployeeLeaveBalance = (
  hireDateStr: string,
  requests: LeaveRequest[],
  bonusRecords: BonusLeaveRecord[]
): LeaveBalance => {
  const today = new Date();
  const cycle = getCurrentCycle(hireDateStr, today);
  const accrued = calculateAccruedInCycle(hireDateStr, today);
  const bonus = bonusRecords.reduce((sum, r) => sum + r.amount, 0);

  let usedAnnual = 0;
  let usedBonus = 0;

  requests.forEach(req => {
    if (req.status !== LeaveStatus.APPROVED) return;
    const start = parseISO(req.startDate);
    const end = parseISO(req.endDate);
    const workdays = calculateWorkdays(start, end);
    let deduction = workdays;
    if (req.type === LeaveType.MORNING_HALF || req.type === LeaveType.AFTERNOON_HALF) deduction = workdays * 0.5;
    else if (req.type === LeaveType.BIRTHDAY || req.type === LeaveType.OFFICIAL) deduction = 0;

    if (isWithinInterval(start, { start: cycle.start, end: cycle.end })) {
      if (req.type === LeaveType.BONUS) usedBonus += deduction;
      else usedAnnual += deduction;
    }
  });

  return {
    accrued, bonus, usedAnnual, usedBonus,
    remainingAnnual: Math.max(0, accrued - usedAnnual),
    remainingBonus: Math.max(0, bonus - usedBonus)
  };
};

