  useEffect(() => { localStorage.setItem('sl_employees_v2', JSON.stringify(employees)); }, [employees]);
  useEffect(() => { localStorage.setItem('sl_requests_v2', JSON.stringify(requests)); }, [requests]);
  useEffect(() => { localStorage.setItem('sl_bonus_v2', JSON.stringify(bonusRecords)); }, [bonusRecords]);

  const handleLogin = (email: string, pass: string) => {
    const found = employees.find(e => e.email === email && e.password === pass);
    if (found) {
      setUser(found);
    } else {
      alert('이메일 또는 비밀번호가 일치하지 않습니다.');
    }
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('sl_user_v2');
  };

  if (!user) {
    return <LoginScreen onLogin={handleLogin} />;
  }

  return (
    <Router>
      <div className="flex h-screen bg-slate-50 overflow-hidden text-slate-900">
