                                <AdminStat label="총 발생" value={`${bal.accrued + bal.bonus}일`} sub={`기본 ${bal.accrued}`} />
                                <AdminStat label="사용" value={`${bal.usedAnnual + bal.usedBonus}일`} sub={`보너스 ${bal.usedBonus}`} />
