const INITIAL_EMPLOYEES: Employee[] = [
  { id: 'admin-main', name: '관리자', email: 'admin@company.com', password: 'admin123', role: Role.ADMIN, hireDate: '2020-01-01' },
];

// --- 4. MAIN APP ---
export default function App() {
  const [user, setUser] = useState<Employee | null>(() => {
    const saved = localStorage.getItem('sl_user_v4');
    return saved ? JSON.parse(saved) : null;
  });
  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('sl_employees_v4');
    return saved ? JSON.parse(saved) : INITIAL_EMPLOYEES;
  });
  const [requests, setRequests] = useState<LeaveRequest[]>(() => {
    const saved = localStorage.getItem('sl_requests_v4');
    return saved ? JSON.parse(saved) : [];
  });
  const [bonusRecords, setBonusRecords] = useState<BonusLeaveRecord[]>(() => {
    const saved = localStorage.getItem('sl_bonus_v4');
    return saved ? JSON.parse(saved) : [];
  });

  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isInviteModalOpen, setIsInviteModalOpen] = useState(false);
  const [isBonusModalOpen, setIsBonusModalOpen] = useState<{empId: string, name: string} | null>(null);

  useEffect(() => { localStorage.setItem('sl_user_v4', JSON.stringify(user)); }, [user]);
  useEffect(() => { localStorage.setItem('sl_employees_v4', JSON.stringify(employees)); }, [employees]);
  useEffect(() => { localStorage.setItem('sl_requests_v4', JSON.stringify(requests)); }, [requests]);
  useEffect(() => { localStorage.setItem('sl_bonus_v4', JSON.stringify(bonusRecords)); }, [bonusRecords]);

  const handleLogin = (email: string, pass: string) => {
    const found = employees.find(e => e.email === email && e.password === pass);
    if (found) {
      setUser(found);
    } else {
      alert('이메일 또는 비밀번호가 일치하지 않습니다.');
    }
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('sl_user_v4');
  };

  if (!user) {
    return <LoginScreen onLogin={handleLogin} />;
  }

  return (
    <Router>
      <div className="flex h-screen bg-[#F1F5F9] overflow-hidden text-slate-800 antialiased font-sans">
        <Sidebar user={user} onLogout={handleLogout} isOpen={sidebarOpen} setIsOpen={setSidebarOpen} />
        <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
          <header className="bg-white/80 backdrop-blur-md border-b px-4 py-3 md:hidden flex justify-between items-center z-30 shadow-sm">
            <button onClick={() => setSidebarOpen(true)} className="p-2 text-slate-600 hover:bg-slate-100 rounded-lg"><Menu size={18}/></button>
            <span className="font-bold text-blue-600 text-lg tracking-tight">SmartLeave</span>
            <div className="w-8"/>
          </header>
          <main className="flex-1 overflow-y-auto">
            <div className="max-w-5xl mx-auto px-4 py-6 md:py-8">
              <Routes>
                <Route path="/dashboard" element={<Dashboard employee={user} requests={requests} bonusRecords={bonusRecords.filter(b => b.employeeId === user.id)} onAddRequest={(d: any) => setRequests(p => [...p, { ...d, id: Math.random().toString(36).substr(2, 9), status: LeaveStatus.PENDING, employeeId: user.id, createdAt: new Date().toISOString() }])} />} />
                <Route path="/history" element={<HistoryView requests={requests.filter(r => r.employeeId === user.id)} />} />
                {user.role === Role.ADMIN && (
                  <>
                    <Route path="/admin/employees" element={
                      <div className="space-y-6 animate-in fade-in duration-400">
                        <div className="flex justify-between items-center">
                          <h2 className="text-xl font-bold text-slate-900">직원 현황 리스트</h2>
                          <button onClick={() => setIsInviteModalOpen(true)} className="bg-slate-900 text-white px-4 py-2 rounded-lg font-bold text-xs flex items-center gap-2 hover:bg-blue-600 transition-all shadow-sm">
                            <UserPlus size={14}/> 직원 등록
                          </button>
                        </div>
                        <div className="grid grid-cols-1 gap-3">
                          {employees.map(emp => {
                            const empRequests = requests.filter(r => r.employeeId === emp.id);
                            const empBonus = bonusRecords.filter(b => b.employeeId === emp.id);
                            const bal = getEmployeeLeaveBalance(emp.hireDate, empRequests, empBonus);
                            return (
                              <div key={emp.id} className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-4 hover:border-blue-200 transition-all group">
                                <div className="flex items-center gap-3 min-w-[180px]">
                                  <div className="w-10 h-10 bg-slate-100 text-slate-600 rounded-lg flex items-center justify-center font-bold text-lg group-hover:bg-blue-600 group-hover:text-white transition-all">{emp.name[0]}</div>
                                  <div>
                                    <div className="flex items-center gap-1.5 font-bold text-slate-900 text-sm">{emp.name}{emp.role === Role.ADMIN && <ShieldCheck size={12} className="text-blue-500"/>}</div>
                                    <p className="text-[10px] text-slate-400 font-medium">{emp.email}</p>
                                  </div>
                                </div>
                                <div className="grid grid-cols-2 lg:grid-cols-4 gap-2 flex-1">
                                  <AdminStat label="총 발생" value={bal.accrued + bal.bonus} />
                                  <AdminStat label="사용" value={bal.usedAnnual + bal.usedBonus} />
                                  <AdminStat label="잔여 연차" value={bal.remainingAnnual} color="text-blue-600" />
                                  <AdminStat label="잔여 보너스" value={bal.remainingBonus} color="text-indigo-600" />
                                </div>
                                <button onClick={() => setIsBonusModalOpen({empId: emp.id, name: emp.name})} className="bg-slate-50 text-slate-600 px-3 py-1.5 rounded-lg font-bold text-[10px] hover:bg-slate-900 hover:text-white transition-all border border-slate-200">
                                  보너스 부여
                                </button>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    } />
                    <Route path="/admin/requests" element={<AdminRequestView requests={requests} setRequests={setRequests} employees={employees} />} />
                  </>
                )}
                <Route path="*" element={<Navigate to="/dashboard" replace />} />
              </Routes>
            </div>
          </main>
        </div>
      </div>

      {isInviteModalOpen && (
        <InviteModal 
          onClose={() => setIsInviteModalOpen(false)} 
          onInvite={(emp: Employee) => { setEmployees(p => [...p, emp]); setIsInviteModalOpen(false); }} 
        />
      )}

      {isBonusModalOpen && (
        <BonusModal 
          target={isBonusModalOpen} 
          onClose={() => setIsBonusModalOpen(null)} 
          onAdd={(rec: BonusLeaveRecord) => { setBonusRecords(p => [...p, rec]); setIsBonusModalOpen(null); }} 
        />
      )}
    </Router>
  );
}

