      config: { systemInstruction: "당신은 인사 관리 AI입니다. 한국어로 친절하게 요약해서 답하세요." }
    });
    return response.text;
  } catch (error) { 
    console.error('Gemini error:', error);
    return "AI 분석 정보를 가져올 수 없습니다."; 
  }
};

