                                  <AdminStat label="보너스 발생" value={bal.bonus} color="text-amber-600" />
                                  <AdminStat label="사용" value={bal.usedAnnual + bal.usedBonus} />
                                  <AdminStat label="잔여 연차" value={bal.remainingAnnual} color="text-blue-600" />
