        <StatCard label="보너스 연차 발생" value={`${balance.bonus}일`} sub="추가 지급분" icon={Award} color="text-amber-600" />
        <StatCard label="잔여 연차" value={`${balance.remainingAnnual}일`} color="text-blue-600" />
