const AdminRequestView = ({ requests, setRequests, employees }: any) => {
  const handleStatusChange = (id: string, status: LeaveStatus) => {
    setRequests((prev: any) => prev.map((r: any) => r.id === id ? { ...r, status } : r));
  };

  const pendingRequests = requests.filter((r: any) => r.status === LeaveStatus.PENDING);
  const otherRequests = requests.filter((r: any) => r.status !== LeaveStatus.PENDING);

  return (
    <div className="space-y-6 animate-in fade-in duration-400">
      <h2 className="text-xl font-bold text-slate-900">연차 승인 관리</h2>

      <div className="space-y-3">
        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider px-1">승인 대기 ({pendingRequests.length})</h3>
        {pendingRequests.length === 0 ? (
          <div className="bg-white p-8 text-center rounded-xl border border-dashed border-slate-200 text-slate-400 text-xs font-medium">대기 중인 요청이 없습니다.</div>
        ) : (
          pendingRequests.map((req: any) => {
            const emp = employees.find((e: any) => e.id === req.employeeId);
            return (
              <div key={req.id} className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 bg-blue-50 text-blue-600 rounded-xl flex items-center justify-center font-bold text-sm">{emp?.name[0]}</div>
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="text-xs font-bold text-slate-900">{emp?.name}</span>
                      <span className="text-[10px] font-bold px-1.5 py-0.5 bg-slate-100 rounded text-slate-600">{LEAVE_TYPE_LABELS[req.type as LeaveType]}</span>
                    </div>
                    <p className="text-[10px] text-slate-400 font-medium">{req.startDate} ~ {req.endDate} ({req.reason})</p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <button onClick={() => handleStatusChange(req.id, LeaveStatus.REJECTED)} className="flex-1 md:flex-none px-4 py-2 bg-slate-50 text-slate-600 rounded-lg text-xs font-bold hover:bg-red-50 hover:text-red-600 transition-all">반려</button>
                  <button onClick={() => handleStatusChange(req.id, LeaveStatus.APPROVED)} className="flex-1 md:flex-none px-4 py-2 bg-blue-600 text-white rounded-lg text-xs font-bold hover:bg-blue-700 transition-all shadow-sm">승인</button>
                </div>
              </div>
            );
          })
        )}
      </div>

      <div className="space-y-3">
        <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider px-1">처리 완료</h3>
        <div className="space-y-2">
          {otherRequests.map((req: any) => {
            const emp = employees.find((e: any) => e.id === req.employeeId);
            return (
              <div key={req.id} className="bg-white/60 p-3 rounded-xl border border-slate-200 flex items-center justify-between gap-4">
                <div className="flex items-center gap-3">
                   <div className="w-7 h-7 bg-slate-100 text-slate-400 rounded-lg flex items-center justify-center font-bold text-xs">{emp?.name[0]}</div>
                   <div>
                     <span className="text-xs font-bold text-slate-700">{emp?.name}</span>
                     <p className="text-[9px] text-slate-400 font-medium">{req.startDate} ({LEAVE_TYPE_LABELS[req.type as LeaveType]})</p>
                   </div>
                </div>
                <div className={`text-[10px] font-bold flex items-center gap-1 ${req.status === LeaveStatus.APPROVED ? 'text-emerald-600' : 'text-red-500'}`}>
                   {req.status === LeaveStatus.APPROVED ? <CheckCircle size={12}/> : <XCircle size={12}/>}
                   {req.status}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

