  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState<Employee | null>(null);

  useEffect(() => { localStorage.setItem('sl_user_v8', JSON.stringify(user)); }, [user]);
  useEffect(() => { localStorage.setItem('sl_employees_v8', JSON.stringify(employees)); }, [employees]);
  useEffect(() => { localStorage.setItem('sl_requests_v8', JSON.stringify(requests)); }, [requests]);
  useEffect(() => { localStorage.setItem('sl_bonus_v8', JSON.stringify(bonusRecords)); }, [bonusRecords]);
  useEffect(() => { localStorage.setItem('sl_settings_v8', JSON.stringify(systemSettings)); }, [systemSettings]);

  const handleLogin = (email: string, pass: string) => {
    const found = employees.find(e => e.email === email && e.password === pass);
    if (found) setUser(found);
    else alert('이메일 또는 비밀번호가 일치하지 않습니다.');
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('sl_user_v8');
  };

  const handleUpdateEmployee = (updatedEmp: Employee) => {
    setEmployees(prev => prev.map(emp => emp.id === updatedEmp.id ? updatedEmp : emp));
    if (user?.id === updatedEmp.id) setUser(updatedEmp);
    setIsEditModalOpen(null);
  };

  const handleDeleteEmployee = (id: string) => {
    if (id === user?.id) {
      alert('현재 로그인 중인 본인 계정은 삭제할 수 없습니다.');
      return;
    }
    setEmployees(prev => prev.filter(emp => emp.id !== id));
    setRequests(prev => prev.filter(req => req.employeeId !== id));
    setBonusRecords(prev => prev.filter(rec => rec.employeeId !== id));
    setIsEditModalOpen(null);
  };

  const sendSlackNotification = async (text: string) => {
    if (!systemSettings.slackWebhookUrl) return;
    try {
      await fetch(systemSettings.slackWebhookUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text }),
      });
    } catch (err) {
      console.error('Slack notification error:', err);
    }
  };

  const handleSubmitRequest = async (formData: any, isEdit = false) => {
    if (!user) return;

    const formatDate = (dateStr: string) => format(parseISO(dateStr), 'yyyy.MM.dd');
    const dateDisplay = formData.startDate === formData.endDate 
      ? formatDate(formData.startDate) 
      : `${formatDate(formData.startDate)} ~ ${formatDate(formData.endDate)}`;

    if (isEdit) {
      setRequests(p => p.map(req => req.id === formData.id ? { 
        ...formData, 
        status: LeaveStatus.PENDING, 
        updatedAt: new Date().toISOString() 
      } : req));
      await sendSlackNotification(`<!channel> [수정] ${user.name} ${dateDisplay} 신청합니다`);
    } else {
      const newId = Math.random().toString(36).substr(2, 9);
      const newRequest: LeaveRequest = { 
        ...formData, 
        id: newId, 
        status: LeaveStatus.PENDING, 
        employeeId: user.id, 
        createdAt: new Date().toISOString() 
      };
      setRequests(p => [...p, newRequest]);
      await sendSlackNotification(`<!channel> ${user.name} ${dateDisplay} 신청합니다`);
    }
  };

  const handleDeleteRequest = (requestId: string) => {
    const target = requests.find(r => r.id === requestId);
    if (!target) {
      console.error('Request not found for deletion:', requestId);
      return;
    }

    if (!confirm('정말 이 신청 내역을 영구 삭제하시겠습니까?')) return;

    // 1. 상태에서 즉시 제거
    setRequests(prev => prev.filter(req => req.id !== requestId));

    // 2. 슬랙 알림 발송
    const applicant = employees.find(e => e.id === target.employeeId);
    if (applicant) {
      const formatDate = (dateStr: string) => format(parseISO(dateStr), 'yyyy.MM.dd');
      const dateDisplay = target.startDate === target.endDate 
        ? formatDate(target.startDate) 
        : `${formatDate(target.startDate)} ~ ${formatDate(target.endDate)}`;
      sendSlackNotification(`<!channel> [삭제] ${applicant.name} ${dateDisplay} 신청건이 삭제되었습니다`);
    }
  };

