    const request = requests.find(r => r.id === requestId);
    if (!request) return;

    setRequests(prev => prev.map(r => r.id === requestId ? { ...r, status: LeaveStatus.APPROVED } : r));

    const employee = employees.find(e => e.id === request.employeeId);
    if (!employee) return;

