            <span className="font-bold text-blue-600">디센트 휴가시스템</span>
            <div className="w-8"/>
          </header>
          <main className="flex-1 overflow-y-auto">
            <div className="max-w-5xl mx-auto px-4 py-6 md:py-8">
              <Routes>
                <Route path="/dashboard" element={<Dashboard employee={user} requests={requests} bonusRecords={bonusRecords.filter(b => b.employeeId === user.id)} onSubmitRequest={handleSubmitRequest} onDeleteRequest={handleDeleteRequest} />} />
                <Route path="/history" element={<HistoryView employee={user} requests={requests.filter(r => r.employeeId === user.id)} bonusRecords={bonusRecords.filter(b => b.employeeId === user.id)} />} />
