// --- 1. TYPES & ENUMS ---
enum Role { ADMIN = 'ADMIN', USER = 'USER' }
enum LeaveStatus { PENDING = 'PENDING', APPROVED = 'APPROVED', REJECTED = 'REJECTED', CANCELLED = 'CANCELLED' }
enum LeaveType {
  ANNUAL = 'ANNUAL',
  MORNING_HALF = 'MORNING_HALF',
  AFTERNOON_HALF = 'AFTERNOON_HALF',
  BONUS = 'BONUS',
  BONUS_MORNING_HALF = 'BONUS_MORNING_HALF',
  BONUS_AFTERNOON_HALF = 'BONUS_AFTERNOON_HALF',
  BIRTHDAY = 'BIRTHDAY',
  OFFICIAL = 'OFFICIAL',
}

const LEAVE_TYPE_LABELS: Record<LeaveType, string> = {
  [LeaveType.ANNUAL]: '연차',
  [LeaveType.MORNING_HALF]: '오전 반차',
  [LeaveType.AFTERNOON_HALF]: '오후 반차',
  [LeaveType.BONUS]: '보너스 연차',
  [LeaveType.BONUS_MORNING_HALF]: '보너스 오전 반차',
  [LeaveType.BONUS_AFTERNOON_HALF]: '보너스 오후 반차',
  [LeaveType.BIRTHDAY]: '생일 반차',
  [LeaveType.OFFICIAL]: '공결',
};

const STATUS_LABELS: Record<LeaveStatus, string> = {
  [LeaveStatus.PENDING]: '대기',
  [LeaveStatus.APPROVED]: '승인',
  [LeaveStatus.REJECTED]: '반려',
  [LeaveStatus.CANCELLED]: '취소됨',
};

interface Employee { id: string; name: string; email: string; password: string; role: Role; hireDate: string; }
interface BonusLeaveRecord { id: string; employeeId: string; amount: number; reason: string; createdAt: string; }
interface LeaveRequest { 
  id: string; 
  employeeId: string; 
  type: LeaveType; 
  startDate: string; 
  endDate: string; 
  isAllDay: boolean; 
  status: LeaveStatus; 
  reason: string; 
  createdAt: string; 
}
interface LeaveBalance { accrued: number; bonus: number; usedAnnual: number; usedBonus: number; remainingAnnual: number; remainingBonus: number; }

// --- 2. UTILS ---
const calculateWorkdays = (start: Date, end: Date): number => {
  if (!isValid(start) || !isValid(end) || start > end) return 0;
  try {
    const days = eachDayOfInterval({ start, end });
    return days.filter(day => !isWeekend(day)).length;
  } catch { return 0; }
};

const getEmployeeLeaveBalance = (hireDateStr: string, requests: LeaveRequest[], bonusRecords: BonusLeaveRecord[]): LeaveBalance => {
  const today = new Date();
  const hireDate = parseISO(hireDateStr);
  const yearsSinceHire = differenceInYears(today, hireDate);
  const cycleStart = addYears(hireDate, yearsSinceHire);
  const finalCycleStart = cycleStart > today ? addYears(hireDate, yearsSinceHire - 1) : cycleStart;
  const cycleEnd = addYears(finalCycleStart, 1);

  const totalMonths = differenceInMonths(today, hireDate);
  let accrued = yearsSinceHire < 1 ? Math.min(totalMonths, 11) : Math.min(15 + Math.floor((yearsSinceHire - 1) / 2), 25);
  const bonus = bonusRecords.reduce((sum, r) => sum + r.amount, 0);

  let usedAnnual = 0, usedBonus = 0;
  requests.forEach(req => {
    if (req.status !== LeaveStatus.APPROVED) return;
    const start = parseISO(req.startDate);
    const workdays = calculateWorkdays(start, parseISO(req.endDate));
    let deduction = [LeaveType.MORNING_HALF, LeaveType.AFTERNOON_HALF, LeaveType.BONUS_MORNING_HALF, LeaveType.BONUS_AFTERNOON_HALF].includes(req.type) ? workdays * 0.5 : workdays;
    if ([LeaveType.OFFICIAL, LeaveType.BIRTHDAY].includes(req.type)) deduction = 0;

    if (isWithinInterval(start, { start: startOfDay(finalCycleStart), end: startOfDay(cycleEnd) })) {
      [LeaveType.BONUS, LeaveType.BONUS_MORNING_HALF, LeaveType.BONUS_AFTERNOON_HALF].includes(req.type) ? usedBonus += deduction : usedAnnual += deduction;
    }
  });

  return {
    accrued, bonus, usedAnnual, usedBonus,
    remainingAnnual: Number((accrued - usedAnnual).toFixed(1)),
    remainingBonus: Number((bonus - usedBonus).toFixed(1))
  };
};

const getUnifiedHistory = (employee: Employee, requests: LeaveRequest[], bonusRecords: BonusLeaveRecord[]) => {
  const history: any[] = [];
  const hireDate = parseISO(employee.hireDate);
  const today = new Date();
  const yearsSinceHire = differenceInYears(today, hireDate);

  if (yearsSinceHire < 1) {
    const months = Math.min(differenceInMonths(today, hireDate), 11);
    for (let i = 1; i <= months; i++) {
      history.push({ id: `acc-${i}`, date: format(addMonths(hireDate, i), 'yyyy-MM-dd'), type: 'EARNED', category: '연차', amount: 1, reason: '월차 발생' });
    }
  } else {
    for (let i = 1; i <= yearsSinceHire; i++) {
      history.push({ id: `acc-y-${i}`, date: format(addYears(hireDate, i), 'yyyy-MM-dd'), type: 'EARNED', category: '연차', amount: Math.min(15 + Math.floor((i - 1) / 2), 25), reason: `${i}년차 정기 연차` });
    }
  }
  bonusRecords.forEach(br => history.push({ id: br.id, date: format(parseISO(br.createdAt), 'yyyy-MM-dd'), type: 'EARNED', category: '보너스', amount: br.amount, reason: br.reason }));
  requests.forEach(req => {
    if (req.status === LeaveStatus.CANCELLED) return;
    const workdays = calculateWorkdays(parseISO(req.startDate), parseISO(req.endDate));
    const deduction = [LeaveType.MORNING_HALF, LeaveType.AFTERNOON_HALF, LeaveType.BONUS_MORNING_HALF, LeaveType.BONUS_AFTERNOON_HALF].includes(req.type) ? workdays * 0.5 : workdays;
    history.push({ id: req.id, date: req.startDate, type: 'USED', category: LEAVE_TYPE_LABELS[req.type], amount: deduction, reason: req.reason, status: req.status });
  });
  return history.sort((a, b) => b.date.localeCompare(a.date));
};

