                <button type="button" onClick={() => handleReject(req.id)} className="px-4 py-2 bg-slate-50 text-slate-600 rounded-lg text-xs font-bold hover:bg-red-50 hover:text-red-600 transition-all">반려</button>
                <button type="button" onClick={() => onApprove(req.id)} className="px-4 py-2 bg-blue-600 text-white rounded-lg text-xs font-bold hover:bg-blue-700 transition-all shadow-sm">승인</button>
