const Dashboard = ({ employee, requests, bonusRecords, onSubmitRequest, onDeleteRequest }: any) => {
  const myRequests = useMemo(() => {
    return requests.filter((r:any) => r.employeeId === employee.id && r.status !== LeaveStatus.CANCELLED);
  }, [requests, employee.id]);

  const approvedRequests = useMemo(() => {
    return myRequests.filter((r:any) => r.status === LeaveStatus.APPROVED);
  }, [myRequests]);

  const balance = useMemo(() => {
    return getEmployeeLeaveBalance(employee.hireDate, approvedRequests, bonusRecords);
  }, [employee.hireDate, approvedRequests, bonusRecords]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingRequest, setEditingRequest] = useState<LeaveRequest | null>(null);
  const [aiRes, setAiRes] = useState('');
  const [loading, setLoading] = useState(false);

  const initialForm = { 
    type: LeaveType.ANNUAL, startDate: format(new Date(), 'yyyy-MM-dd'), endDate: format(new Date(), 'yyyy-MM-dd'), 
    isAllDay: true, startTime: '09:00', endTime: '18:00', reason: '' 
  };
  const [form, setForm] = useState(initialForm);

  const openApplyModal = () => {
    setEditingRequest(null);
    setForm(initialForm);
    setIsModalOpen(true);
  };

  const openEditModal = (req: LeaveRequest) => {
    setEditingRequest(req);
    setForm({
      type: req.type,
      startDate: req.startDate,
      endDate: req.endDate,
      isAllDay: req.isAllDay,
      startTime: req.startTime || '09:00',
      endTime: req.endTime || '18:00',
      reason: req.reason
    });
    setIsModalOpen(true);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-400">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white p-5 rounded-2xl border shadow-sm">
        <div>
          <h2 className="text-xl font-bold text-slate-900">{employee.name}님, 좋은 하루입니다</h2>
          <p className="text-xs text-slate-500 mt-1 font-medium">입사일: {employee.hireDate} • 근속 현황을 기반으로 연차가 자동 계산됩니다.</p>
        </div>
        <button onClick={openApplyModal} className="bg-blue-600 text-white px-5 py-2.5 rounded-xl font-bold text-sm flex items-center justify-center gap-2 hover:bg-blue-700 shadow-lg shadow-blue-100 transition-all"><PlusCircle size={18}/>연차 신청</button>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard label="법정 연차 발생" value={`${balance.accrued}일`} sub="근로기준법 기준" icon={Scale} />
        <StatCard label="보너스 연차" value={`${balance.bonus}일`} sub="지급된 추가 연차" icon={Award} color="text-amber-600" />
        <StatCard label="잔여 법정 연차" value={`${balance.remainingAnnual}일`} color="text-blue-600" />
        <StatCard label="잔여 보너스" value={`${balance.remainingBonus}일`} color="text-indigo-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-white p-6 rounded-2xl border shadow-sm">
            <div className="flex items-center gap-2 mb-3 text-blue-600 font-bold text-xs uppercase tracking-widest"><MessageSquare size={16}/> AI 데이터 분석</div>
            {aiRes ? (
              <div className="text-xs bg-slate-50 p-4 rounded-xl mb-4 leading-relaxed text-slate-700 border border-slate-100 whitespace-pre-wrap">{aiRes}</div>
            ) : (
              <p className="text-slate-400 mb-4 text-xs font-medium leading-relaxed">직원님의 연차 소진율과 근속 데이터를 분석하여 인사이트를 제공합니다.</p>
            )}
            <button 
              disabled={loading} 
              onClick={async () => { 
                setLoading(true); 
                const res = await askGemini(`직원 ${employee.name} (입사일: ${employee.hireDate})의 현재 잔여 연차는 ${balance.remainingAnnual}일, 보너스 연차는 ${balance.remainingBonus}일입니다. 연차 사용 현황을 분석하고 제안을 해주세요.`) || '';
                setAiRes(res); 
                setLoading(false); 
              }} 
              className="w-full bg-slate-50 text-slate-700 py-2.5 rounded-xl font-bold text-xs hover:bg-slate-100 transition-all border border-slate-100"
            >
              {loading ? 'AI 분석 중...' : '연차 분석 요청 →'}
            </button>
          </div>
        </div>

        <div className="lg:col-span-2">
          <div className="bg-white rounded-2xl border shadow-sm overflow-hidden">
            <div className="px-6 py-4 border-b bg-slate-50/50 flex justify-between items-center">
              <h3 className="font-bold text-xs text-slate-500 uppercase tracking-widest">최근 신청 현황</h3>
              <Link to="/history" className="text-xs font-bold text-blue-600 hover:underline transition-all">전체 보기</Link>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs">
                <thead className="bg-slate-50 text-slate-400 font-bold border-b">
                  <tr>
                    <th className="px-6 py-3.5">종류</th>
                    <th className="px-6 py-3.5">기간</th>
                    <th className="px-6 py-3.5">상태</th>
                    <th className="px-6 py-3.5 text-right">관리</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {myRequests.length === 0 ? (
                    <tr><td colSpan={4} className="px-6 py-16 text-center text-slate-400 font-medium italic">신청 내역이 존재하지 않습니다.</td></tr>
                  ) : myRequests.slice(0, 10).map((req: LeaveRequest) => (
                    <tr key={req.id} className="hover:bg-slate-50/30 transition-colors group">
                      <td className="px-6 py-4 font-bold text-slate-700">{LEAVE_TYPE_LABELS[req.type]}</td>
                      <td className="px-6 py-4 text-slate-500 font-medium">{req.startDate}{req.startDate !== req.endDate && ` ~ ${req.endDate}`}</td>
                      <td className="px-6 py-4">
                        <span className={`px-2.5 py-1 rounded-full font-bold text-[10px] ${
                          req.status === LeaveStatus.APPROVED ? 'bg-emerald-50 text-emerald-600' : 
                          req.status === LeaveStatus.REJECTED ? 'bg-red-50 text-red-600' : 
                          'bg-amber-50 text-amber-600'
                        }`}>{STATUS_LABELS[req.status]}</span>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end gap-1 opacity-40 group-hover:opacity-100 transition-opacity">
                          <button type="button" onClick={() => openEditModal(req)} className="p-2 text-slate-400 hover:text-blue-600 rounded-lg hover:bg-blue-50 transition-all"><Edit2 size={15}/></button>
                          <button 
                            type="button" 
                            onClick={(e) => { e.preventDefault(); e.stopPropagation(); onDeleteRequest(req.id); }} 
                            className="p-2 text-slate-400 hover:text-red-500 rounded-lg hover:bg-red-50 transition-all"
                          >
                            <Trash2 size={15} className="pointer-events-none" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in duration-200">
            <div className="px-6 py-4 border-b flex justify-between items-center bg-slate-50">
              <h3 className="font-bold text-sm text-slate-900">연차 {editingRequest ? '수정' : '신청'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-1 hover:bg-slate-200 rounded-lg transition-colors"><X size={18}/></button>
            </div>
            <div className="p-6 space-y-5">
              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">연차 종류</label>
                <select className="w-full border-2 border-slate-100 p-3 rounded-xl text-sm font-bold bg-slate-50 outline-none focus:border-blue-500 transition-colors" value={form.type} onChange={e => setForm({...form, type: e.target.value as LeaveType})}>
                  {Object.entries(LEAVE_TYPE_LABELS).map(([val, label]) => <option key={val} value={val}>{label}</option>)}
                </select>
              </div>
              <div className="flex items-center gap-2">
                <input type="checkbox" id="all-day" checked={form.isAllDay} onChange={e => setForm({...form, isAllDay: e.target.checked})} className="w-4 h-4 rounded text-blue-600 focus:ring-blue-500 cursor-pointer"/>
                <label htmlFor="all-day" className="text-sm font-bold text-slate-600 cursor-pointer">종일 신청</label>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">시작일</label>
                  <input type="date" className="w-full border-2 border-slate-100 p-2.5 rounded-xl text-xs font-bold bg-slate-50 focus:border-blue-500 outline-none" value={form.startDate} onChange={e => setForm({...form, startDate: e.target.value})}/>
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">종료일</label>
                  <input type="date" className="w-full border-2 border-slate-100 p-2.5 rounded-xl text-xs font-bold bg-slate-50 focus:border-blue-500 outline-none" value={form.endDate} onChange={e => setForm({...form, endDate: e.target.value})}/>
                </div>
              </div>
              {!form.isAllDay && (
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">시작 시간</label>
                    <input type="time" className="w-full border-2 border-slate-100 p-2.5 rounded-xl text-xs font-bold bg-slate-50 focus:border-blue-500 outline-none" value={form.startTime} onChange={e => setForm({...form, startTime: e.target.value})}/>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">종료 시간</label>
                    <input type="time" className="w-full border-2 border-slate-100 p-2.5 rounded-xl text-xs font-bold bg-slate-50 focus:border-blue-500 outline-none" value={form.endTime} onChange={e => setForm({...form, endTime: e.target.value})}/>
                  </div>
                </div>
              )}
              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">신청 사유</label>
                <textarea required className="w-full border-2 border-slate-100 p-3 rounded-xl text-xs font-medium bg-slate-50 h-24 resize-none focus:border-blue-500 outline-none" placeholder="휴가 사유를 간단히 적어주세요..." value={form.reason} onChange={e => setForm({...form, reason: e.target.value})} />
              </div>
              <button 
                type="button" 
                onClick={() => { onSubmitRequest(editingRequest ? { ...editingRequest, ...form } : form, !!editingRequest); setIsModalOpen(false); }} 
                className="w-full py-3.5 bg-blue-600 text-white rounded-xl font-bold text-sm hover:bg-blue-700 shadow-lg shadow-blue-100 transition-all"
              >
                {editingRequest ? '내역 수정하기' : '신청 완료하기'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatCard = ({ label, value, sub, icon: Icon, color = "text-slate-900" }: any) => (
  <div className="bg-white p-5 rounded-2xl border shadow-sm flex flex-col justify-between transition-all hover:shadow-md">
    <div className="flex items-center justify-between mb-2">
      <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{label}</span>
      {Icon && <Icon size={16} className="text-slate-200" />}
    </div>
    <div>
      <div className={`text-2xl font-black ${color} tracking-tight`}>{value}</div>
      {sub && <p className="text-[10px] text-slate-400 font-bold mt-1">{sub}</p>}
    </div>
