  useEffect(() => { localStorage.setItem('sl_requests_v9', JSON.stringify(requests)); }, [requests]);
  useEffect(() => { localStorage.setItem('sl_bonus_v9', JSON.stringify(bonusRecords)); }, [bonusRecords]);
  useEffect(() => { localStorage.setItem('sl_settings_v9', JSON.stringify(systemSettings)); }, [systemSettings]);

  const handleLogin = (email: string, pass: string) => {
    const found = employees.find(e => e.email === email && e.password === pass);
    if (found) setUser(found);
    else alert('이메일 또는 비밀번호가 일치하지 않습니다.');
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('sl_user_v9');
  };

  const handleUpdateEmployee = (updatedEmp: Employee) => {
    setEmployees(prev => prev.map(emp => emp.id === updatedEmp.id ? updatedEmp : emp));
