const AdminRequestView = ({ requests, onApprove, onDelete, setRequests, employees }: any) => {
  const handleReject = (id: string) => setRequests((prev: any) => prev.map((r: any) => r.id === id ? { ...r, status: LeaveStatus.REJECTED } : r));
  const pendingRequests = useMemo(() => {
    return requests.filter((r: any) => r.status === LeaveStatus.PENDING);
  }, [requests]);

  return (
    <div className="space-y-6 animate-in fade-in duration-400">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-bold text-slate-900">대기 중인 연차 승인</h2>
        <span className="px-3 py-1 bg-amber-50 text-amber-600 rounded-full text-xs font-bold border border-amber-100">미처리 {pendingRequests.length}건</span>
      </div>
      <div className="space-y-3">
        {pendingRequests.length === 0 ? (
          <div className="bg-white p-20 text-center rounded-3xl border border-dashed text-slate-400 text-sm font-bold">승인을 기다리는 요청이 모두 처리되었습니다.</div>
        ) : pendingRequests.map((req: any) => {
          const emp = employees.find((e: any) => e.id === req.employeeId);
          return (
            <div key={req.id} className="bg-white p-5 rounded-2xl border shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-5 transition-all hover:shadow-md">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center font-black text-lg shadow-sm">{emp?.name[0]}</div>
                <div>
                  <div className="flex items-center gap-2.5 mb-1">
                    <span className="text-sm font-black text-slate-900">{emp?.name}</span>
                    <span className="text-[10px] font-bold px-2 py-1 bg-slate-100 rounded-lg text-slate-600 uppercase tracking-tight">{LEAVE_TYPE_LABELS[req.type as LeaveType]}</span>
                  </div>
                  <p className="text-xs text-slate-500 font-bold mb-0.5">{req.startDate} ~ {req.endDate}</p>
                  <p className="text-[11px] text-slate-400 italic">" {req.reason} "</p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <button 
                  type="button" 
                  onClick={(e) => { e.preventDefault(); e.stopPropagation(); onDelete(req.id); }} 
                  className="p-3 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all" 
                  title="신청 내역 삭제"
                >
                  <Trash2 size={20} className="pointer-events-none" />
                </button>
                <button type="button" onClick={() => handleReject(req.id)} className="px-5 py-2.5 bg-slate-100 text-slate-600 rounded-xl text-xs font-bold hover:bg-red-50 hover:text-red-600 transition-all">반려</button>
                <button type="button" onClick={() => onApprove(req.id)} className="px-5 py-2.5 bg-blue-600 text-white rounded-xl text-xs font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-100">즉시 승인</button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

