        <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 text-white px-5 py-2.5 rounded-xl font-bold text-sm flex items-center justify-center gap-2 hover:bg-blue-700 shadow-lg shadow-blue-100 transition-all"><PlusCircle size={18}/>연차 신청</button>
      </div>
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4"><StatCard label="법정 연차 발생" value={`${balance.accrued}일`} sub="기준법 자동 계산" icon={Scale} /><StatCard label="보너스 연차" value={`${balance.bonus}일`} sub="지급된 추가 일수" icon={Award} color="text-amber-600" /><StatCard label="잔여 법정 연차" value={`${balance.remainingAnnual}일`} color="text-blue-600" /><StatCard label="잔여 보너스" value={`${balance.remainingBonus}일`} color="text-indigo-600" /></div>
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1"><div className="bg-white p-6 rounded-2xl border shadow-sm flex flex-col h-full"><div className="flex items-center gap-2 mb-3 text-blue-600 font-bold text-xs uppercase tracking-widest"><MessageSquare size={16}/> AI 연차 분석</div>{aiRes ? <div className="text-xs bg-slate-50 p-4 rounded-xl mb-4 leading-relaxed text-slate-700 border border-slate-100 whitespace-pre-wrap">{aiRes}</div> : <p className="text-slate-400 mb-4 text-xs font-medium leading-relaxed">직원님의 연차 현황을 분석하여 휴식 일정을 추천해드립니다.</p>}<button disabled={loading} onClick={async () => { setLoading(true); const res = await askGemini(`직원 ${employee.name} (입사일: ${employee.hireDate})의 현재 잔여 법정 연차는 ${balance.remainingAnnual}일입니다. 분석해주세요.`); setAiRes(res || ''); setLoading(false); }} className="w-full bg-slate-50 text-slate-700 py-2.5 rounded-xl font-bold text-xs hover:bg-slate-100 border mt-auto">{loading ? '분석 중...' : '연차 분석 요청 →'}</button></div></div>
        <div className="lg:col-span-2"><div className="bg-white rounded-2xl border shadow-sm overflow-hidden"><div className="px-6 py-4 border-b bg-slate-50/50 flex justify-between items-center"><h3 className="font-bold text-[10px] text-slate-400 uppercase tracking-widest">최근 신청 현황</h3><Link to="/history" className="text-[10px] font-bold text-blue-600 hover:underline">전체 보기</Link></div><div className="overflow-x-auto"><table className="w-full text-left text-[11px]"><thead className="bg-slate-50 text-slate-400 font-bold border-b"><tr><th className="px-6 py-3 uppercase">종류</th><th className="px-6 py-3 uppercase">기간</th><th className="px-6 py-3 uppercase">상태</th><th className="px-6 py-3 text-right uppercase">관리</th></tr></thead><tbody className="divide-y divide-slate-100">{myRequests.length === 0 ? <tr><td colSpan={4} className="px-6 py-16 text-center text-slate-400 italic">내역이 없습니다.</td></tr> : myRequests.slice(0, 10).map((req: LeaveRequest) => (<tr key={req.id} className="hover:bg-slate-50/30 group"><td className="px-6 py-3.5 font-bold text-slate-800">{LEAVE_TYPE_LABELS[req.type]}</td><td className="px-6 py-3.5 text-slate-500">{req.startDate}{req.startDate !== req.endDate ? ` ~ ${req.endDate}` : ''}</td><td className="px-6 py-3.5"><span className={`inline-flex px-2 py-0.5 rounded-full font-bold text-[9px] ${req.status === LeaveStatus.APPROVED ? 'bg-emerald-50 text-emerald-600' : req.status === LeaveStatus.REJECTED ? 'bg-red-50 text-red-600' : 'bg-amber-50 text-amber-600'}`}>{STATUS_LABELS[req.status]}</span></td><td className="px-6 py-3.5 text-right"><div className="flex items-center justify-end gap-1 opacity-20 group-hover:opacity-100 transition-opacity"><button onClick={() => { setEditingRequest(req); setForm({...req}); setIsModalOpen(true); }} className="p-1.5 text-slate-400 hover:text-blue-600"><Edit2 size={13}/></button><button onClick={() => onDeleteRequest(req.id)} className="p-1.5 text-slate-400 hover:text-red-500"><Trash2 size={13}/></button></div></td></tr>))}</tbody></table></div></div></div>
      </div>
      {isModalOpen && (<div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-[100] flex items-center justify-center p-4"><div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 space-y-5 animate-in zoom-in duration-200"><div className="flex justify-between items-center border-b pb-4"><h3 className="font-bold text-sm text-slate-900">연차 {editingRequest ? '수정' : '신청'}</h3><button onClick={() => setIsModalOpen(false)}><X size={18}/></button></div><div className="space-y-4"><div className="space-y-1.5"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">종류</label><select className="w-full border p-2.5 rounded-xl text-sm font-bold bg-slate-50" value={form.type} onChange={e => setForm({...form, type: e.target.value as LeaveType})}>{Object.entries(LEAVE_TYPE_LABELS).map(([val, label]) => <option key={val} value={val}>{label}</option>)}</select></div><div className="flex items-center gap-2"><input type="checkbox" id="all-day" checked={form.isAllDay} onChange={e => setForm({...form, isAllDay: e.target.checked})} className="w-4 h-4 rounded text-blue-600"/><label htmlFor="all-day" className="text-sm font-bold text-slate-600">종일 신청</label></div><div className="grid grid-cols-2 gap-4"><div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">시작일</label><input type="date" className="w-full border p-2 rounded-lg text-xs font-bold" value={form.startDate} onChange={e => setForm({...form, startDate: e.target.value})}/></div><div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">종료일</label><input type="date" className="w-full border p-2 rounded-lg text-xs font-bold" value={form.endDate} onChange={e => setForm({...form, endDate: e.target.value})}/></div></div><div className="space-y-1"><label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">사유</label><textarea required className="w-full border p-3 rounded-xl text-xs font-medium bg-slate-50 h-24 resize-none" value={form.reason} onChange={e => setForm({...form, reason: e.target.value})} placeholder="신청 사유..."/></div><button onClick={() => { onSubmitRequest(form, !!editingRequest); setIsModalOpen(false); }} className="w-full py-3.5 bg-blue-600 text-white rounded-xl font-bold text-sm shadow-lg shadow-blue-100">{editingRequest ? '수정하기' : '신청하기'}</button></div></div></div>)}
    </div>
  );
};

const StatCard = ({ label, value, sub, icon: Icon, color = "text-slate-900" }: any) => (
  <div className="bg-white p-5 rounded-2xl border shadow-sm flex flex-col justify-between hover:shadow-md transition-all"><div className="flex items-center justify-between mb-2"><span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{label}</span>{Icon && <Icon size={16} className="text-slate-200" />}</div><div><div className={`text-2xl font-black ${color}`}>{value}</div>{sub && <p className="text-[10px] text-slate-400 font-bold mt-1">{sub}</p>}</div></div>
