                  bonusRecords={bonusRecords.filter(b => b.employeeId === isHistoryModalOpen.id)} 
                  carriedOverRecords={carriedOverRecords.filter(c => c.employeeId === isHistoryModalOpen.id)} 
                  isModal={true} 
