xl text-xs font-medium bg-slate-50 h-24 resize-none" value={form.reason} onChange={e => setForm({...form, reason: e.target.value})} placeholder="신청 사유..."/></div><button onClick={() => { onSubmitRequest(form, !!editingRequest); setIsModalOpen(false); }} className="w-full py-3.5 bg-blue-600 text-white rounded-xl font-bold text-sm shadow-lg shadow-blue-100">{editingRequest ? '수정하기' : '신청하기'}</button></div></div></div>)}
    </div>
  );
