          <button onClick={onLogout} className="flex items-center gap-2 w-full px-3.5 py-2.5 text-red-500 text-xs font-bold hover:bg-red-50 rounded-xl transition-all"><LogOut size={16}/>로그아웃</button>
        </div>
      </div>
