const STATUS_LABELS: Record<LeaveStatus, string> = {
  [LeaveStatus.PENDING]: '대기',
  [LeaveStatus.APPROVED]: '승인',
  [LeaveStatus.REJECTED]: '반려',
  [LeaveStatus.CANCELLED]: '취소됨',
};

