k={() => setRequests((p: any) => p.map((r: any) => r.id === req.id ? { ...r, status: LeaveStatus.REJECTED } : r))} className="px-6 py-3 bg-slate-100 text-slate-600 rounded-2xl text-xs font-black hover:bg-slate-200 transition-all">반려</button><button onClick={() => onApprove(req.id)} className="px-8 py-3 bg-blue-600 text-white rounded-2xl text-xs font-black shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95">즉시 승인</button></div></div>); })}</div></div>
