  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[150] flex items-center justify-center p-4"><div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in duration-200 flex flex-col max-h-[90vh]"><div className="px-8 py-5 border-b flex justify-between items-center bg-slate-50 shrink-0"><div><h3 className="font-black text-slate-900">{target.name}님 {title} 관리</h3><p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">현재 총 합계: {total}일</p></div><button onClick={onClose} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X size={22}/></button></div><div className="flex-1 overflow-y-auto p-8 space-y-10"><section className="space-y-4"><h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b pb-3 flex items-center gap-2"><History size={14}/> 상세 지급 내역</h4><div className="space-y-3">{records.length === 0 ? <div className="text-center py-10 text-slate-400 text-xs italic bg-slate-50 rounded-2xl border-2 border-dashed font-bold shadow-inner">기록된 내역이 없습니다.</div> : records.map((rec: any) => (<div key={rec.id} className="flex items-center justify-between p-4 bg-white border border-slate-100 rounded-2xl hover:border-blue-200 transition-all group shadow-sm"><div className="flex items-center gap-4"><div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-xs shadow-inner ${rec.amount < 0 ? 'bg-red-50 text-red-600' : (accentColor === 'indigo' ? 'bg-indigo-50 text-indigo-600' : 'bg-amber-50 text-amber-600')}`}>{rec.amount > 0 ? '+' : ''}{rec.amount}</div><div><p className="text-xs font-black text-slate-800">{rec.reason}</p><p className="text-[9px] text-slate-400 font-bold mt-1 tracking-tighter">{rec.createdAt.split('T')[0]}</p></div></div><button onClick={() => onDeleteRecord(rec.id)} className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={16}/></button></div>))}</div></section><section className="bg-slate-50/80 p-6 rounded-3xl border border-slate-200 space-y-6 shadow-inner"><h4 className="text-[10px] font-black text-slate-900 uppercase tracking-widest text-center">지급 또는 차감 등록</h4><div className="flex items-center justify-center gap-8"><button type="button" onClick={() => setAmount(amount - 0.5)} className="w-12 h-12 rounded-2xl bg-white border-2 border-slate-100 text-slate-600 text-2xl font-black hover:bg-slate-50 transition-all shadow-sm active:scale-95">-</button><div className={`text-4xl font-black w-32 text-center tracking-tighter ${amount < 0 ? 'text-red-600' : 'text-slate-900'}`}>{amount}일</div><button type="button" onClick={() => setAmount(amount + 0.5)} className={`w-12 h-12 rounded-2xl text-white text-2xl font-black transition-all shadow-xl active:scale-95 ${btnBg}`}>+</button></div><div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">상세 사유</label><textarea required className="w-full border-2 border-white p-4 rounded-2xl text-sm font-medium bg-white h-24 resize-none focus:border-blue-500 outline-none transition-all shadow-sm" value={reason} onChange={e => setReason(e.target.value)} placeholder="사유를 입력해 주세요..." /></div><button onClick={() => { if(!reason.trim()) return alert('사유를 입력해주세요.'); onAdd({ id: Math.random().toString(36).substr(2, 9), employeeId: target.empId, amount, reason, createdAt: new Date().toISOString() }); setReason(''); setAmount(1); }} className={`w-full py-4 text-white rounded-2xl font-black text-sm transition-all shadow-xl active:scale-95 ${amount < 0 ? 'bg-red-500 hover:bg-red-600 shadow-red-100' : 'bg-slate-900 hover:bg-blue-600 shadow-slate-200'}`}>내역 {amount < 0 ? '차감' : '추가'} 완료</button></section></div></div></div>
  );
};

