  const loc = useLocation();
  const NavItem = ({ to, icon: Icon, label }: any) => (
    <Link to={to} onClick={() => setIsOpen(false)} className={`flex items-center gap-3 px-4 py-3 rounded-2xl transition-all duration-300 font-black text-xs ${loc.pathname === to ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}><Icon size={18} /><span>{label}</span></Link>
  );
  return (
    <>
      {isOpen && <div className="fixed inset-0 bg-black/30 backdrop-blur-sm z-40 md:hidden" onClick={() => setIsOpen(false)} />}
      <div className={`fixed inset-y-0 left-0 z-50 w-72 bg-white border-r flex flex-col p-6 transition-transform md:relative md:translate-x-0 ${isOpen ? 'translate-x-0' : '-translate-x-full shadow-2xl md:shadow-none'}`}>
        <div className="flex items-center gap-3 mb-12 px-2"><div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white font-black text-xl shadow-xl shadow-blue-100">D</div><h1 className="text-base font-black tracking-tighter text-slate-900">디센트 휴가시스템</h1></div>
        <nav className="flex-1 space-y-2">
          <NavItem to="/dashboard" icon={LayoutDashboard} label="대시보드" /><NavItem to="/history" icon={History} label="연차 변동 내역" />
          {user.role === Role.ADMIN && (<div className="pt-10 space-y-2"><p className="text-[10px] font-black text-slate-300 uppercase px-4 mb-4 tracking-widest flex items-center gap-2"><ShieldCheck size={12}/> Admin Panel</p><NavItem to="/admin/employees" icon={Users} label="임직원 관리" /><NavItem to="/admin/requests" icon={Calendar} label="연차 승인 센터" /><NavItem to="/admin/settings" icon={Settings} label="시스템 환경 설정" /></div>)}
        </nav>
        <div className="mt-auto pt-6 border-t border-slate-100">
          <div className="px-4 py-4 bg-slate-50 rounded-2xl mb-4 flex items-center gap-3"><div className="w-8 h-8 bg-white border border-slate-200 rounded-full flex items-center justify-center font-black text-[10px] text-slate-400">{user.name[0]}</div><div className="min-w-0"><div className="flex items-center gap-1.5"><p className="text-xs font-black truncate text-slate-800">{user.name}</p>{user.role === Role.ADMIN && <ShieldCheck size={12} className="text-blue-500"/>}</div><p className="text-[9px] text-slate-400 font-bold truncate">{user.email}</p></div></div>
          <button onClick={onLogout} className="flex items-center gap-3 w-full px-4 py-3 text-red-500 text-xs font-black hover:bg-red-50 rounded-2xl transition-all group"><LogOut size={18} className="group-hover:-translate-x-1 transition-transform"/> 시스템 로그아웃</button>
        </div>
      </div>
    </>
  );
};

const DeleteConfirmModal = ({ type, onCancel, onConfirm }: any) => (
  <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[200] flex items-center justify-center p-4 animate-in fade-in duration-200">
    <div className="bg-white w-full max-w-sm rounded-3xl shadow-2xl p-8 text-center space-y-6 animate-in zoom-in duration-200">
      <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto shadow-inner"><AlertTriangle size={36}/></div>
      <div><h4 className="text-xl font-black text-slate-900">정말 삭제할까요?</h4><p className="text-xs text-slate-400 font-bold mt-2 leading-relaxed">{type === 'EMPLOYEE' ? '직원의 모든 휴가 기록과 계정 정보가 사라집니다.' : '해당 내역이 시스템에서 완전히 삭제됩니다.'}<br/>이 작업은 되돌릴 수 없습니다.</p></div>
      <div className="flex gap-3 pt-2"><button onClick={onCancel} className="flex-1 py-3.5 bg-slate-100 text-slate-600 rounded-2xl font-black text-sm hover:bg-slate-200 transition-all">취소</button><button onClick={onConfirm} className="flex-1 py-3.5 bg-red-500 text-white rounded-2xl font-black text-sm hover:bg-red-600 shadow-xl shadow-red-100 transition-all active:scale-95">확인 및 삭제</button></div>
    </div>
  </div>
);

const EmployeeModal = ({ initialData, onClose, onSave, onDelete }: any) => {
  const [form, setForm] = useState(initialData || { name: '', email: '', password: '', role: Role.USER, hireDate: format(new Date(), 'yyyy-MM-dd') });
  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[150] flex items-center justify-center p-4"><div className="bg-white w-full max-w-sm rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in duration-200"><div className="px-8 py-5 border-b flex justify-between items-center bg-slate-50"><h3 className="font-black text-slate-900">직원 {initialData ? '정보 수정' : '신규 등록'}</h3><button onClick={onClose} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X size={22}/></button></div><form className="p-8 space-y-5" onSubmit={e => { e.preventDefault(); onSave(initialData ? { ...initialData, ...form } : { ...form, id: Math.random().toString(36).substr(2, 9) }); }}><div className="space-y-1.5"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">성명</label><input required className="w-full border-2 border-slate-100 p-3.5 rounded-2xl text-sm font-black outline-none focus:border-blue-500 bg-slate-50" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></div><div className="space-y-1.5"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">이메일 계정</label><input required type="email" className="w-full border-2 border-slate-100 p-3.5 rounded-2xl text-sm font-black outline-none focus:border-blue-500 bg-slate-50" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} /></div><div className="grid grid-cols-2 gap-4"><div className="space-y-1.5"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">비밀번호</label><input required className="w-full border-2 border-slate-100 p-3.5 rounded-2xl text-sm font-black outline-none bg-slate-50" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} /></div><div className="space-y-1.5"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">입사일</label><input type="date" className="w-full border-2 border-slate-100 p-3.5 rounded-2xl text-sm font-black outline-none bg-slate-50" value={form.hireDate} onChange={e => setForm({ ...form, hireDate: e.target.value })} /></div></div><div className="pt-6 flex flex-col gap-3"><button type="submit" className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black text-sm shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95">정보 저장하기</button>{initialData && <button type="button" onClick={() => onDelete(initialData.id)} className="w-full py-4 bg-white text-red-500 border-2 border-red-50 rounded-2xl font-black text-sm hover:bg-red-50 flex items-center justify-center gap-2">직원 계정 삭제</button>}</div></form></div></div>
  );
};

